INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giana Sisters: Twisted Dreams - Owltimate Edition', 'Giana Sisters: Twisted Dreams – Owltimate Edition offers classic 2D platforming fun in meticulously detailed 3D environments. Players can turn cute Giana into a punk version of herself at the press of a button, transforming the game’s star, the soundtrack and even the world. This overhaul isn’t merely cosmetic: Giana’s punk persona is a critical to overcoming obstacles and solving particularly tricky situations. In her sweet incarnation, Giana whirls gracefully over obstacles and opponents, but when ‘punked up’ she smashes through stone blocks with mighty dashes and can master her environment by bouncing off walls.' FROM games WHERE igdb_id = 78869 ON CONFLICT (game_id, language_code) DO NOTHING;
