INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squidlit', 'Every day is a wonderful day for invertebrates! Come join the Squidlits of Blipston for a squishy adventure of spoopy castles, muffins, and wiggles! Made with classic handheld technology in mind, Squidlit strives to be the closest modern recreation of GameBoy game-design methods on the market.' FROM games WHERE igdb_id = 86574 ON CONFLICT (game_id, language_code) DO NOTHING;
