INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombslinger', 'A Bomberman-inspired Wild West action game with bombs! A solo hardcore reinvention of the iconic explosive action! Wear the poncho of the Bombslinger, a ruthless bandit turned peaceful rancher on a quest to avenge the murder of his missus and destruction of his ranch at the hands of his former posse. Bomb your way through hordes of enemies and master the classic bomb-slinging gameplay in a solo adventure with procedurally generated levels, character progression with skill upgrades, and a variety of offensive and defensive items. And when you want a break from the solo adventure, take the fight to your friends in hectic 4-player deathmatch battles!' FROM games WHERE igdb_id = 32572 ON CONFLICT (game_id, language_code) DO NOTHING;
