INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evergarden', '"Escape into a mysterious world of puzzles that will awaken your mind, and quiet your soul."  "Lose yourself in an endlessly satisfying puzzle game set in the midst of a mysterious forest world. Transform your garden by combining plants into strange new forms, and unearth deeply hidden secrets as you become engrossed in the game’s calming rhythm. Wander into the forest and help bring it back to life with the help of Fen, your creature guide. Evergarden may feel familiar at first, but you will discover it is like no game you have played before."' FROM games WHERE igdb_id = 107191 ON CONFLICT (game_id, language_code) DO NOTHING;
