INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loyalty and Blood: Viktor Origins', 'Years after leaving to wander Overworld, Viktor returns home to find his mother long dead and his brother in command of the Legion. As he aims to pick up the pieces of the life he left behind, Viktor finds himself in the midst of a gathering storm that will change Overworld forever...' FROM games WHERE igdb_id = 89774 ON CONFLICT (game_id, language_code) DO NOTHING;
