INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('smoke-and-sacrifice', 86442, '2018-05-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co275h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6y4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smoke and Sacrifice', 'In Smoke and Sacrifice players assume the role of Sachi, a young mother on a quest to discover the fate of her child. The game takes place in a darkly fantastical world where grotesque plant life and animals roam and harsh societal customs rule. Taking cues from modern survival classics, Smoke and Sacrifice evolves the genre with its intensely personal story and complex ecosystem. Creatures forage, mate, breed and prey on one another, creating a living world. Only by taming the game’s wilds can Sachi hope to unravel the mystery at the heart of Smoke and Sacrifice. Depicted in a beautiful, hand-painted style, Smoke and Sacrifice’s storybook visuals disguise its brutal story of motherhood and survival. Sachi doesn’t just have to worry about the game’s antagonists - the entire game world poses a threat. Players can alter the behaviour of plant and animal life, but this may also limit the resources Sachi has to craft items from. The deadly smoke also poses unique challenges throughout the game, altering enemy as well as player behaviour.' FROM games WHERE igdb_id = 86442 ON CONFLICT (game_id, language_code) DO NOTHING;
