INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quantum Replica', 'Hide in time as you explore a sealed off cyberpunk metropolis in Quantum Replica, a mix of fast-paced stealth and metroidvania. In Quantum Replica, you are an unregistered entity who has managed to enter the cyberpunk heart of this sprawling megacity. Immediately made Most Wanted by its security forces, your urge to explore the city in search of answers will be far from easy. With nowhere to hide, your only refuge is time itself.' FROM games WHERE igdb_id = 32642 ON CONFLICT (game_id, language_code) DO NOTHING;
