INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gravity-hop-space-adventure', 111392, '2018-10-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hoe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5jaa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Hop: Space Adventure', 'Tap the screen to stop gravity to find your way back home! A challenging, fast paced, arcade casual game. Story: You are the Commander of a spaceship out on a mission in deep space. When the spaceship gets hit, and loses most of its systems, you are left to fend for yourself. With the help of the crew only survivors - Emma and Jim, you embark on a mission to get back home using gravity forces. Features: ● EASY CONTROLS. One tap mechanics. ● SKILL GAME. Improve playing skills as you play. ● CAMPAIGN. Full engrossing story that will gradually introduce you to the Gravity Hop world. ● CHALLENGES. Challenging levels with increased difficulty. ● POWER-UPS. Use unique power-ups to overcome hard challenges. ● UPGRADE your spaceship and power-ups. ● LOTS OF LEVELS. Play hundreds of levels with more added in regular updates. ● LEADERBOARDS. Prove who is the best in the world on the global leaderboards. ● FREE to download! --- Gravity Hop is completely free to play. There are optional in-app purchases available, but not required to rule the game.' FROM games WHERE igdb_id = 111392 ON CONFLICT (game_id, language_code) DO NOTHING;
