INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul Saga: Episode 1', 'Soul Saga is a traditional role-playing video game in the vein of the Final Fantasy, Suikoden, Breath of Fire, and Persona video game series. Battles are initiated similarly to Chrono Trigger, where combat begins upon the player directing the character into an enemy in the world map. Once initiated, combat consists of a turn based battle system similar to Final Fantasy X. The game will also have airship battles, similar to Skies of Arcadia. Exploration of the overworld map will also be a major aspect of gameplay, with the player being able to explore on foot similarly to Final Fantasy VII, and by airship similarly to Skies of Arcadia.' FROM games WHERE igdb_id = 8174 ON CONFLICT (game_id, language_code) DO NOTHING;
