INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('7th-sea-a-pirates-pact', 113865, '2018-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28ri.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5yps.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7th Sea: A Pirate''s Pact', 'Fight for what''s right—as an up and coming pirate! Battle slavers, sea monsters, and your own corrupt government to become a hero of the high seas. But will you betray your own crew for wealth and power?  7th Sea: A Pirate''s Pact is a 200,000-word interactive adventure novel by Danielle Lauzon, set in the world of the table-top role playing game 7th Sea. It''s entirely text-based, without graphics or sound effects, and fueled by the vast, unstoppable power of your imagination.  Looking for adventure at sea? You’ll get more than you bargained for when you end up joining a pirate crew. These pirates are known among sailors for having their own moral code, one that is now yours. You''ll have the chance to rescue prisoners, uncover a secret plot, and even build a navy to liberate an island fort full of slaves.  But you''ll also be tempted to break your pirate bonds to seek your own gain. Would you still free the slaves if you could take out your own rivals instead? How far will you go to save your friends? And when you uncover corruption in your homeland, will you choose villainy or vengeance?  Earn your crew''s loyalty and they might make you their captain, but get careless and you might have to walk the plank!' FROM games WHERE igdb_id = 113865 ON CONFLICT (game_id, language_code) DO NOTHING;
