INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Max Xeno', 'On that day humans start to face a crisis of destruction... A new title from the RPG "METAL MAX" about the story of human and tank is here! "METAL MAX Xeno" now here on PlayStation! Taking place at the ruined metropolis known as "Death Tokio" the story is one that actively involves the protagonist and tanks (vehicles) starting with the R Wolf. Numerous possibilities for the tank customization awaits, containing features such as weapons, engines and equipment. So enjoy this reincarnated true post-apocalyptic RPG now!' FROM games WHERE igdb_id = 74874 ON CONFLICT (game_id, language_code) DO NOTHING;
