INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Matter', 'Red Matter is a story-driven VR puzzle adventure game set during a dystopian sci-fi Cold War. Take on the role of Agent Epsilon, an astronaut of the Atlantic Union dispatched to an abandoned Volgravian moon base on a frozen, faraway planet. Your mission: to investigate a shady top secret research project.' FROM games WHERE igdb_id = 109907 ON CONFLICT (game_id, language_code) DO NOTHING;
