INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Strike Force', 'In Marvel Strike Force, ready for battle alongside allies and arch-rivals in this action-packed, visually-stunning free-to-play game for your phone or tablet. An assault on Earth has begun and Super Heroes and Super Villains are working together to defend it! Lead the charge by assembling your ultimate squad, including Spider-Man, Doctor Strange, Groot, Rocket Raccoon, Loki, Venom, Elektra, Captain America and Iron Man, as you enter strategic combat against an all-new enemy threat. It’s time to fight! Gather your squad and prepare for the battle to save Earth!' FROM games WHERE igdb_id = 76164 ON CONFLICT (game_id, language_code) DO NOTHING;
