INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO DC Super-Villains', 'Lego DC Super-Villains is a Lego-themed action-adventure platform video game developed by Traveller''s Tales. The fourth installment in the Lego Batman series of games, it is a spin-off that focuses entirely on villains of the DC Universe; it is the first in the series to do so since the villain levels from Lego Batman: The Videogame. While the core gameplay follows the same style as past Lego titles, including the addition of a two-player cooperative multiplayer mode, DC Super-Villains is the first title to incorporate a customized character into the story.' FROM games WHERE igdb_id = 102321 ON CONFLICT (game_id, language_code) DO NOTHING;
