INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tokyo-clanpool', 36931, '2018-10-05', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hds.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar36mh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Clanpool', 'Tokyo Clanpool is a Dungeon RPG where you’ll take your party of heroines deeper and deeper into the tower to counter the monster threat and learn the truth of its origin. Equip Digiskins to customize characters’ skills and abilities while navigating mazelike corridors in first-person perspective. Turn-based combat is fast and strategic, and with your team’s ether-based powers, you can even float or dig tunnels to alter the structure of dungeons. But you’ll also have to keep an eye on your citizens’ approval ratings. If your actions are favorable, you can earn valuable bonuses, but if it falls too low, your entire cabinet could resign! Is your administration up to the task?' FROM games WHERE igdb_id = 36931 ON CONFLICT (game_id, language_code) DO NOTHING;
