INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mosha Online', 'Mosha Online An Online RPG handcrafted with ❤ for Web, PC and Android that lets you compete socially with your friends to become the most famous Dream Walker Hero of all.  ¡You are the Hero! Select your stats, equip your weapons and capture Moshans in the World of Mosha. Explore the World, Be Social, join a Guild, hunt with a Party, Top the leaderboards, Play Minigames, Loot items and design your own worlds in this stress relieving never-ending adventure.' FROM games WHERE igdb_id = 126275 ON CONFLICT (game_id, language_code) DO NOTHING;
