INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuza 3 Remastered', 'Yakuza 3 Remastered is an updated version of Yakuza 3, developed by Ryu Ga Gotoku Studio and published by Sega. Released as part of The Yakuza Remastered Collection in 2019, the remaster features improved graphics, a higher frame rate, and restored content that was cut from the original Western release. The game follows protagonist Kazuma Kiryu as he manages an orphanage in Okinawa while being drawn back into conflicts with the yakuza.' FROM games WHERE igdb_id = 103015 ON CONFLICT (game_id, language_code) DO NOTHING;
