INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizard of Legend', '"Wizard of Legend is a fast paced 2D dungeon crawler where you assume the role of a powerful wizard on his quest for fame and glory! Combine powerful spells and quick reflexes to overcome all of the challenges and become a Wizard of Legend!" "Battle your way through each challenge by defeating powerful conjured enemies! Collect valuable spells and relics and build up your magical arsenal to fit your playstyle! Achieve mastery over magic by chaining spells together to create devastating combination attacks! Face each council member in combat and earn your right to become a Wizard of Legend!"' FROM games WHERE igdb_id = 19935 ON CONFLICT (game_id, language_code) DO NOTHING;
