INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fist of the North Star: Lost Paradise', 'Hokuto Ga Gotoku is a video game by Sega scheduled to be released for the PlayStation 4 in 2018. It is a 3D action-adventure game by the developers of Sega''s Yakuza series (known as Ryū Ga Gotoku in Japan) and features the voice cast of the Yakuza series portraying established Hokuto no Ken characters. The story takes place in an alternate universe, as Kenshiro wanders into the post-apocalyptic haven of Eden in search of his lost love Yuria.' FROM games WHERE igdb_id = 55112 ON CONFLICT (game_id, language_code) DO NOTHING;
