INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imperatum', 'You are an agent, thrown headfirst into your first mission trying to unravel the mystery of the veil that is consuming the galaxy. Created by former professional gamers and AAA developers, Imperatum is an Action RPG set in a future Sci-Fi universe. The game focuses on the core ARPG ''trinity'' mechanics of fast-paced combat, deep character customization and tons of loot!' FROM games WHERE igdb_id = 55316 ON CONFLICT (game_id, language_code) DO NOTHING;
