INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Inner Friend', 'The Inner Friend features a rich visual environment, supported by an immersive soundscape and a cinematic soundtrack enhancing immersion and emotional moments. Movement, imagery, and music are the main ways for the player to interact with the Shadow, their guide throughout the descent. Dark and scary, mysterious at times, the world of The Inner Friend is a surrealist representation of memories and fears.' FROM games WHERE igdb_id = 104280 ON CONFLICT (game_id, language_code) DO NOTHING;
