INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thronebreaker: The Witcher Tales', 'Thronebreaker is a single player role-playing game set in the world of The Witcher that combines narrative-driven exploration with unique puzzles and card battle mechanics. This game spins a truly regal tale of Meve, a war-veteran and queen of two Northern Realms - Lyria and Rivia. Facing an imminent Nilfgaardian invasion, Meve is forced to once again enter the warpath and set out on a dark journey of destruction and revenge.' FROM games WHERE igdb_id = 107300 ON CONFLICT (game_id, language_code) DO NOTHING;
