INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-hulk-deathwing-enhanced-edition', 95068, '2018-05-22', 66, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98yf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar394w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Hulk: Deathwing - Enhanced Edition', 'Space Hulk: Deathwing - Enhanced Edition is a First-Person Shooter for PS4 and PC based on Games Workshop’s cult classic board game set in Warhammer 40,000 universe. Expanding upon the original game, and featuring a host of new content, new features and a richer multiplayer mode, the Enhanced Edition is the ultimate Space Hulk: Deathwing experience on PC and for the first time on PlayStation 4 Play as a Terminator of the Deathwing – the feared 1st Company comprised of the elite of the secretive Space Marine Chapter, the Dark Angels – and engage in a desperate battle against Genestealers, within the claustrophobic confines of a Space Hulk. Grow stronger, gaining skills, new abilities, and powerful equipment as you earn experience across perilous missions. The Enhanced Edition brings a host of fresh features to enjoy in both solo and multiplayer: a new class, an expanded arsenal, deadly new enemies , a deep online customisation system, and a new Special Missions mode bringing infinite replayability with randomly-generated missions for every game chapter. This edition marks the game’s first release on PlayStation 4, with all its additional content available through free updates for all present and future Space Hulk: Deathwing players on PC. Strap on your Terminator armour and equip the iconic weaponry of the Space Marines to overcome the threats lurking deep within Space Hulk Olethros!' FROM games WHERE igdb_id = 95068 ON CONFLICT (game_id, language_code) DO NOTHING;
