INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow of the Tomb Raider: Croft Edition', 'Experience Lara Croft’s defining moment as she becomes the Tomb Raider. In Shadow of the Tomb Raider, Lara must master a deadly jungle, overcome terrifying tombs, and persevere through her darkest hour. As she races to save the world from a Maya apocalypse, Lara must become the Tomb Raider she is destined to be. The Croft Edition includes: - 48H early access* - Additional Skills Booster Pack - Xbox Live Avatar outfit* - Season Pass - 3 additional weapons/outfits - Digital OST' FROM games WHERE igdb_id = 99122 ON CONFLICT (game_id, language_code) DO NOTHING;
