INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vestige', 'Vestige is a room-scale VR documentary that uses volumetric capture to take the viewer on a journey into the mind of Lisa as she remembers her lost love. Within an empty void, fragments of past memories appear of their life together and eventually lead us to the shocking moment of Erik’s death.' FROM games WHERE igdb_id = 113069 ON CONFLICT (game_id, language_code) DO NOTHING;
