INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taiko no Tatsujin: Drum ''n'' Fun!', 'Enjoy the cult classic arcade rhythm game from Japan in the comfort of your own home! Play to the beat using your own drum with a wide variety of new songs and challenge your friends to prove who has the best taiko skills. Use motion controls to enjoy Taiko like never before! Unlock beloved characters to help you on your journey to become a legendary taiko drummer! Utilize the interactive features of the Nintendo Switch to connect, share, and play with family and friends.' FROM games WHERE igdb_id = 104992 ON CONFLICT (game_id, language_code) DO NOTHING;
