INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bigfoot Quest', 'Embark on an adventure of a lifetime and explore the forests of the Pacific Northwest in search of the famously elusive Bigfoot. Many books have been written, many blurry photos have been taken, but has anyone really found Bigfoot? Discover beautiful landscapes, find clues, and solve puzzles along the way in this point-and-click style puzzle adventure game. Your Uncle Henry has set up camp deep in the forest of the Pacific Northwest in search of the mysterious Bigfoot. He asks for your help as he is close to discovering the location of Bigfoot’s den. Will you find Bigfoot?' FROM games WHERE igdb_id = 90752 ON CONFLICT (game_id, language_code) DO NOTHING;
