INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run Jump Fail', 'You wanna run? You wanna jump? You''re gonna fail. Again. And Again.  But its fun to fail...right?  Take control of HappyMan and hop skip and jump your way past low walls, big balls and spinning red things! A bunch of obstacles await, so get to it.' FROM games WHERE igdb_id = 97029 ON CONFLICT (game_id, language_code) DO NOTHING;
