INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monster-boy-and-the-cursed-kingdom', 25599, '2018-12-04', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27mg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4nld.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Boy and the Cursed Kingdom', 'A legendary game series returns with an all-new adventure! Monster Boy is a colourful side-scrolling action adventure created in cooperation with Ryuichi Nishizawa, the creator of the Wonder Boy Monster World series (Trademark of SEGA Corporation Japan). Monster Boy is being created to bring back the enjoyment of classic games that shine by simplicity. Pure, exciting gameplay; upbeat music and smooth graphics. You''ll need to overcome huge bosses, find hidden passages, discover powerful equipment and use all your wits and skills to remove a powerful curse. Monster Boy can transform into 5 different creatures, each with their own skills and abilities. Take advantage of all the unique powers to open new paths and advance in an epic story. Monster Boy is a love letter to gaming from the 80''s and 90''s - will you join us and celebrate together with us?' FROM games WHERE igdb_id = 25599 ON CONFLICT (game_id, language_code) DO NOTHING;
