INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nintendo-labo-toy-con-02-robot-kit', 85307, '2018-04-20', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5bcr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/i1t3oazpenvb8baotqoj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendo Labo: Toy-Con 02 - Robot Kit', 'Make a Toy-Con Robot suit…to become a robot in the game! Fold engineered, pre-cut cardboard sheets by following interactive instructions and then suit up to get playing. Thanks to the adjustable straps, one size fits all! Wreck in-game environments and beat challenges to unlock powerful abilities. Then, discover how the Toy-Con Robot comes to life with Nintendo Switch technology and, in Toy-Con Garage, invent new ways to play! Bust out your own markers, stickers, and more to customize your Toy-Con Robot suit—or enter the Hanger to customize your in-game robot’s appearance. By moving your hands and feet, you can manoeuvre the robot in the game, unleash your moves, or make sound effects! As you play, keep track of your robot’s rank, points earned, and unlocked special abilities. Discover the mechanics behind the Toy-Con Robot and how the Nintendo Switch technology brings it to life. If you’re feeling competitive, take on a friend with their own Toy-Con Robot* in a two-player battle mode on a single screen! Then go beyond in the included Toy-Con Garage mode to invent new ways to play with your Toy-Con Robot or create your very own Toy-Con projects.' FROM games WHERE igdb_id = 85307 ON CONFLICT (game_id, language_code) DO NOTHING;
