INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bring-you-home', 87031, '2018-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2956.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjao.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bring You Home', 'From the creators of Love You to Bits, Alike Studio presents BRING YOU HOME BRING YOU HOME unravels the story of Polo, a humble alien hero who will traverse all kinds of worlds in a frenzied chase to rescue his kidnapped alien pet. BRING YOU HOME is a cute and accessible, purely visual, family-friendly puzzle adventure… with a twist in the gameplay. You don’t control the hero, you control the level ITSELF! How? Change and rearrange the pieces of every level to unveil the right path for Polo! With this innovative mechanic, even failing can be fun! If poor Polo finds a deadly but hilarious fate, just go back in time and rewind the level. Venture into oodles of worlds stuffed with magical characters, bizarre surprises, and many treacherous dangers – all to catch the captors of your missing pet. Will you get to the bottom of this mystery? INVENTIVE Explore a mind-boggling game mechanic that allows you to control the environment around you! UNEXPECTED Jump from world to world in dozens of levels all around the universe. You never know what’s gonna happen next! SILLY Discover all the wacky pitfalls in every level – you don’t want to miss them! ADORABLE Find and collect nostalgic pictures you took with your lovely pet! Oh, sweet memories…' FROM games WHERE igdb_id = 87031 ON CONFLICT (game_id, language_code) DO NOTHING;
