INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swooning Over Stans', 'Ever watch Gravity Falls and think, man, that Stan sure is hot? Well, indulge that thought by playing this Grunkle Dating Sim, a Gravity Falls fangame! A summer road trip leads to an unexpected pause in Gravity Falls. Can you capture the heart of one of the Mystery Shack’s most eligible bachelors? Or will you leave empty-handed?' FROM games WHERE igdb_id = 178753 ON CONFLICT (game_id, language_code) DO NOTHING;
