INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luigi''s Mansion', 'G-g-ghosts! All this ghost-catching tomfoolery pays off! As you suck ''em up with your Poltergust 3000, you could also rake in millions in hidden, in-game riches for our hard-luck hero. Make sure to search every area using the Game Boy Horror''s map on your touchscreen and activate its Boo Radar to track down every Boo in the mansion or spot ghosts'' weak points. After beating and capturing boss ghosts, you can select their portraits from the gallery to best your own score in tense rematches—a new feature in the Nintendo 3DS version!' FROM games WHERE igdb_id = 90109 ON CONFLICT (game_id, language_code) DO NOTHING;
