INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SaGa: Scarlet Grace - Ambitions', 'SaGa Scarlet Grace is the latest title in the SaGa series, released in December 2016 for the PlayStation Vita in Japan. An enhanced edition of the game subtitled "Hiiro no Yabou" (lit. Scarlet Ambition) was also released for the Nintendo Switch, PlayStation 4, on August 2, 2018, which featured a few enhancements to fix minor gameplay issues as well as additional story content.' FROM games WHERE igdb_id = 119373 ON CONFLICT (game_id, language_code) DO NOTHING;
