INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Grand Cruise', 'Come aboard and experience the pirate’s life in ONE PIECE Grand Cruise for PlayStationVR. Be prepared to be swept away in the first ONE PIECE VR experience. Step onto the famous Thousand Sunny ship and meet the legendary Straw Hat Pirates including Luffy, Zoro, Nami, Sanji, and many more while you brave fierce battles and fire cannons to defend the ship! Choose rooms to explore within the ship and feel what it’s like to be a pirate.' FROM games WHERE igdb_id = 47292 ON CONFLICT (game_id, language_code) DO NOTHING;
