INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zone of The Enders: The 2nd Runner Mars', 'Relive the experience Zone of The Enders: The 2nd Runner M∀RS as a full-length remaster of the classic fast-paced 3D robot action game, recreated in VR, native 4K and in full surround sound. Enter Jehuty’s cockpit and fly through martian skies!' FROM games WHERE igdb_id = 68284 ON CONFLICT (game_id, language_code) DO NOTHING;
