INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('florence', 87672, '2018-02-13', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co295l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc8t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Florence', 'Florence is an interactive storybook from the award-winning lead designer of Monument Valley about the heart-racing highs and heartbreaking lows of a young woman''s very first love. Experience every beat of Florence and Krish''s relationship through a series of mini-game vignettes - from flirting to fighting, from helping each other grow... to growing apart. Drawing inspiration from ''slice of life'' graphic novels and webcomics, Florence is an intimate and unforgettable story.' FROM games WHERE igdb_id = 87672 ON CONFLICT (game_id, language_code) DO NOTHING;
