INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fortune-499', 'Fortune-499 is a game about money and magic. You play a fortune teller working in the magical resources department of a large corporation. You engage in day-to-day office activities such as forwarding emails, attending meetings, fighting back hordes of monsters, and dealing with printer jams. With some tricky magic up your sleeve and your job on the line, it''s up to you to build a future out of the hand you''ve been dealt.' FROM games WHERE igdb_id = 87812 ON CONFLICT (game_id, language_code) DO NOTHING;
