INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('charade-maniacs', 69343, '2018-08-09', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70tg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar28ev.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charade Maniacs', 'Charade Maniacs is an otome visual novel full of romance, mystery, and adventure. In the near future... Summer break was around the corner. Hiyori Sena, a sophomore in high school, was living a peaceful life. One day, as she was walking home with her childhood friend, a masked figure appeared before them. The two were abducted and taken to a strange world with two moons. When they awoke, they met nine others in the same predicament. In their confusion, the mysterious figure began to speak. "Welcome to Arcadia!" "In this world, if you perform for us, your wildest dreams can come true!" In order to find their way home, the group was forced to work together and act in an assortment of scenes from a drama. They were also made aware that a traitor walked among them... What could be the motive of this traitor? And why are they all being forced to act? Unable to fully trust anyone, who''s hand will she take in the end?' FROM games WHERE igdb_id = 69343 ON CONFLICT (game_id, language_code) DO NOTHING;
