INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhem II SE: The Cave', 'Rhem II SE: The Cave is an intricate pure-puzzle first person adventure game. The player explores a hidden city far beneath the earths surface. RHEM II SE features non-linear gameplay non-violent story and mind-bending puzzles. NEW compared to the original RHEM 2 - extended version of the original RHEM 2 - new area and new puzzles - build-in color-picker' FROM games WHERE igdb_id = 112131 ON CONFLICT (game_id, language_code) DO NOTHING;
