INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SOS', 'SOS is an interactive game show where 16 entertaining performers are dropped onto La Cuna Island with one simple goal – get off La Cuna Island. Players must find a relic, signal for extraction, and grab a spot on the rescue chopper while out-thinking opponents and fending off monster hordes. Survivors will be rewarded with fame and fortune, not to mention their lives.' FROM games WHERE igdb_id = 72334 ON CONFLICT (game_id, language_code) DO NOTHING;
