INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirty Bomb', 'Dirty Bomb takes first person shooters back to their purest roots in a fast-paced team game that will challenge even the most competent players. This game won’t hold your hand, in fact it is more likely to kick your teeth in. With no controller support or aim assist, all that lies between you and certain death is player skill and reaction. Work together or die alone in the most challenging team-based FPS.' FROM games WHERE igdb_id = 1902 ON CONFLICT (game_id, language_code) DO NOTHING;
