INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skeletal-dance-party', 101064, '2018-10-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/i6qinjdqistkbczqjbil.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkzd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skeletal Dance Party', 'Necromancers! Paladins! Skeletons! Monsters! Oh, my! You play as Reva, a young fox-eared necromancer who embarks on a quest to host an awesome dance party for all her friends… who happen to be the reanimated skeletons of her enemies. Cast spells, solve puzzles, and bring your enemies back from the dead as you dance towards the noblest goal any necromancer has ever had: PARTYING! ‘Skeletal Dance Party’ resurrects the charming voxel style and hypnotically bouncy physics of its viral predecessor, ‘Skeletal Dance Simulator’, into a full-bodied narrative experience. By casting spells, moving objects and people with telekinesis, and resurrecting your enemies as more skeletons to join your party crew and reach the all-important goal of having the biggest party ever!' FROM games WHERE igdb_id = 101064 ON CONFLICT (game_id, language_code) DO NOTHING;
