INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omen of Sorrow', 'Omen of Sorrow is a classic 2D, four-button fighting game, with Unreal Engine 4 powered graphics, a cast of 12 characters inspired by classical horror, fantasy and mythology, and a battle system designed from the ground up to leverage player skill, rather than stats or random chance, featuring deep combat mechanics that favor movement and spacing over tight execution to provide an engaging experience for pros and newcomers alike!' FROM games WHERE igdb_id = 27070 ON CONFLICT (game_id, language_code) DO NOTHING;
