INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyper Light Drifter: Special Edition', 'The wait is over, the worldwide acclaimed game Hyper Light Drifter is finally here with this impressive Special Edition! Runs at 60fps, includes new exclusive content and all the previously released remastered for a perfectly inmersive gaming experience to play anywhere. Explore a beautiful, vast and ruined world riddled with dangers and lost technologies. Echoes of a dark and violent past resonate throughout a savage land, steeped in treasure and blood. Hyper Light Drifter is an action adventure RPG in the vein of the best 16­bit classics, with modernized mechanics and designs on a much grander scale.' FROM games WHERE igdb_id = 107295 ON CONFLICT (game_id, language_code) DO NOTHING;
