INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxes Inc.', 'Welcome to our small warehouse. Boxes Inc. is an exciting game - puzzle. Your role is to earn money by processing the parcels. Every day you''ll encounter new rules becoming more difficult. - It''s not just joyfully, but also useful! - It affects your intellect, memory and concentration. - Develops precision and responsibility.' FROM games WHERE igdb_id = 97231 ON CONFLICT (game_id, language_code) DO NOTHING;
