INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burnout Paradise Remastered', 'Welcome back to Paradise City! Make action your middle name as you rule the streets in Burnout Paradise Remastered. Tear up the town from hectic downtown avenues to wild mountain roads. Relive the high-octane stunts and wanton destruction of one of the greatest arcade-driving games ever! Burnout Paradise Remastered provides the ultimate driving playground for you and your friends to play online. This remaster includes the 8 main DLC packs from the Year of Paradise, including the Big Surf Island update, meticulously recreated and ready to wreck!' FROM games WHERE igdb_id = 78153 ON CONFLICT (game_id, language_code) DO NOTHING;
