INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes of Umbra', 'Heroes of Umbra is a 2D side-scrolling online RPG in-progress that plays similar to side-scrolling RPGs like MapleStory and Castlevania. Whether you’re on an Android device, a desktop computer, or the OUYA console, online play is platform-agnostic. You can connect and play with your friends anywhere with Internet access, or just solo single-player if you can’t get (or don’t want to be) online. The game is completely free-to-play and DRM-free.' FROM games WHERE igdb_id = 3226 ON CONFLICT (game_id, language_code) DO NOTHING;
