INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rage In Peace', 'Rage in Peace is a story-driven action adventure with elements of surprise and memorization. Unravel the last day of Timmy''s life, as he races against time to get back home and fulfill his sole dream of dying peacefully in his pajamas, in the warmth of home, in peace, and with no drama.' FROM games WHERE igdb_id = 86617 ON CONFLICT (game_id, language_code) DO NOTHING;
