INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Bomberman R: Shiny Edition', 'Super Bomberman R Shiny Edition includes bonus content: - Eight Shiny Bomberman Brothers set, Golden Vic Viper Bomber. - Story Mode - A campaign playable alone or with a friend in local co-op. Join the eight Bomberman heroes and help them to defeat the Evil Emperor Buggler. - Battle Mode - The classic and fun Battle Mode is back. Play with up to eight players locally or eight players online. - Grand Prix - Grand Prix is a new competitive mode in which teamwork is key. - For one player, also features multiplayer support.' FROM games WHERE igdb_id = 103368 ON CONFLICT (game_id, language_code) DO NOTHING;
