INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harem Hotel', 'Harem Hotel is an Adult Visual Novel with Dating Sim and Training themes… Develop relationships, skills, and your hotel, with 18 beautiful and fleshed out characters. Featuring fully animated and completely uncensored lewd scenes, an array of stats and traits to build and unlock, many outfits to use, unique characters and fetishes, over 560 unique events, over 14,000 images, and way, way more to come.' FROM games WHERE igdb_id = 127632 ON CONFLICT (game_id, language_code) DO NOTHING;
