INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nepenthe', 'You wake up with no memory. Your day is starting off great! Nepenthe is a hand-drawn RPG with a terrible sense of humor. Set in the strange world of Carithia, you play as a mysterious bald dude who lost his memory. Yes, you read that right. Meet some very polite monsters, and battle both them and your sense of self-dignity in epic bullet-hell fight scenes!' FROM games WHERE igdb_id = 100600 ON CONFLICT (game_id, language_code) DO NOTHING;
