INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('adventure-of-a-lifetime', 97221, '2018-04-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28ti.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armgg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure of a Lifetime', '"There’s something I need to get back. Something precious that sank into the ocean years ago." The story takes place on the World Heritage-listed Ogasawara Islands. After a four-year absence, Hiroki Mizuno returns to the island during his summer vacation to help his grandmother with her shop. The story begins as he encounters a beautiful blonde girl, Emily, on the deck of the ferry on his way to the island. Emily has run away from home. She has her mind set on retrieving “sunken treasure”. Chisa, an old friend with whom Hiroki reconnects on the island, provides some insight. “The Ghost Ship―that''s what we call one of the shipwrecks around here." It’s said that the treasure Emily is after lies in a shipwreck that disappears each time there’s a storm. Emily, the beautiful blonde-haired girl. Chisa, the childhood friend with golden, suntanned skin. This summer, pass the days on a tropical island with two beautiful girls, scuba diving, and adventure! Their destination: the “Ghost Ship”. Somewhere just past where the sky meets the sea...' FROM games WHERE igdb_id = 97221 ON CONFLICT (game_id, language_code) DO NOTHING;
