INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter: Hogwarts Mystery', 'Harry Potter: Hogwarts Mystery is a role-playing video game developed and published by Jam City under license from Portkey Games. Based on J.K. Rowling''s Harry Potter novels, the game is set in the Wizarding World and situated before the events of the series. Players step into the shoes of a customizable character enrolling in Hogwarts School of Witchcraft and Wizardry, where they engage in various activities including attending magic classes, learning spells, dueling rivals, dating characters, playing Quidditch, and embarking on quests.' FROM games WHERE igdb_id = 77631 ON CONFLICT (game_id, language_code) DO NOTHING;
