INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Razed', 'RAZED is a lightning-fast, single-player platform racing game that''s all about speedrunning. Sprint through dynamic neon levels in the quickest time possible, employing skills such as super-speed bursts, mega-jumps, drifts, stomps and strafes to bypass obstacles and uncover shortcuts to propel yourself up the online leaderboards. But there''s a catch: powers cost momentum, and if your energy falls too low your shoes (and you) could very well explode...' FROM games WHERE igdb_id = 86041 ON CONFLICT (game_id, language_code) DO NOTHING;
