INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MarisaLand Legacy', 'Twilight Frontier''s latest release is here! A Touhou Project inspired work: "MarisaLand Legacy" Eat mushrooms to increase your height in this easy to control 2D side scrolling action game! But it''s not only her height which has changed, the number of players too! Marisa''s adventure starts once more...!! The publisher of this game on Steam is DLsite Official.' FROM games WHERE igdb_id = 111204 ON CONFLICT (game_id, language_code) DO NOTHING;
