INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treadnauts', 'Treadnauts combines frantic group combat with a kiss of physics-based finesse. Players fight as colorful tanks in bright, tactical playgrounds. By moving with chutzpah, pilots can pull off spectacular acrobatics, soaring through the air and raining deadly mortar shots on their foes.' FROM games WHERE igdb_id = 54785 ON CONFLICT (game_id, language_code) DO NOTHING;
