INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nintendo-labo-toy-con-01-variety-kit', 85308, '2018-04-20', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kdm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vg8zp0dbbassevraeocp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendo Labo: Toy-Con 01 - Variety Kit', 'Make two Toy-Con RC Cars, a Fishing Rod, a Motorbike, a House, and a Piano using engineered, pre-cut cardboard sheets and fun, interactive instructions. Then, Play! Steer the RC Car, reel in fish from the ocean, drive your Motorbike, interact with a creature in the House, and play tunes on the Piano. Then, discover how it all comes to life with Nintendo Switch technology and, in Toy-Con Garage, invent new ways to play! Grab your own markers, stickers, and more to customize your Toy-Con creations. Steer the Toy-Con RC Car manually, have it self-drive, or challenge a friend to a match with two Toy-Con RC Cars*. Race the CPU with the Toy-Con Motorbike, collect targets on bumpy terrain, or create your own tracks. Catch in-game fish with the Toy-Con Fishing Rod, then view what you’ve caught or create original fish with Toy-Con Piano in Aquarium mode! You can also play quick tunes with Toy-Con Piano, or record your own music. Insert blocks into your Toy-Con House to feed a creature, play minigames with it, and who knows what else! Then go beyond in the included Toy-Con Garage mode to invent new ways to play with each Toy-Con project in the Variety Kit or create your very own!' FROM games WHERE igdb_id = 85308 ON CONFLICT (game_id, language_code) DO NOTHING;
