INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tanglewood', 'Set in a fictional world, this puzzle-platforming game follows a young creature, Nymn, who is separated from the family pack after the sun sets. Unable to get back to the safety of the underground home, Nymn must find a way to survive the night terrors and get to morning. Tanglewood''s world is a dangerous one after dark, and Nymn must use skills of evasion, special abilities, traps and trickery to defeat predators.' FROM games WHERE igdb_id = 104602 ON CONFLICT (game_id, language_code) DO NOTHING;
