INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret Little Haven', 'An adventure game about old computers, community, creativity, fandom, gender, and the internet. Alex Cole is a teenage trans girl in 1999 who has yet to figure herself out. She spends much of her free time on the internet, browsing a fan forum for her favorite magical girl show, and chatting with her friends. Join her on her story of self-discovery through friendship and media as she explores her computer for the treasures and curiosities of the early internet.' FROM games WHERE igdb_id = 90060 ON CONFLICT (game_id, language_code) DO NOTHING;
