INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nicky: The Home Alone Golf Ball', 'A poor and home alone golf ball needs your help to get your goal - to find his home ( a hole in a golf track ) in less movements as possible. Nicky moves only with mouse, you just need to drag, look at some point and release. The game is funny and challenging!' FROM games WHERE igdb_id = 95614 ON CONFLICT (game_id, language_code) DO NOTHING;
