INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('unlikely-heroes', 80882, '2018-01-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/atr1xrto4zaxnoamvtoo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/csr40efmf190qzepve7p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unlikely Heroes', 'Long long ago, in a land far far away, the vicious dragon came from above. Alas, the dragon destroyed our homeland and villagers awaited for a true hero. Wait...What?! The Mighty Warrior retired already? Fine, then I''ll leap into this grand adventure of Dragons and save the world myself! Game features: **Gather Your Heroes** Only you and your heroic comrades can save the world! Characters like Lonely Shepherd and Tavern Maid await you to take them to march to victory! **Fight Through the World** Travel through the thick Forest, across the vast Desert, through the boundless Snowland, and traverse the Enchanting Land to complete all of the challenging mazes. **Rebuild the Village** Find the missing villagers, rebuild every house and workshop, help your fellas renovate the village! **Train as an Alchemist** Practice Alchemy, Transmute lead into gold, create the elixir of immortality and craft all kinds of items that will help you on your journey!' FROM games WHERE igdb_id = 80882 ON CONFLICT (game_id, language_code) DO NOTHING;
