INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dig or Die', 'You are a representative of the CRAFT & Co company. You are selling automated fabrication tools across the galaxy when your spacecraft crashes into a hostile planet. Use the tools you sell and the local resources to build up all of what you''ll need to survive and eventually be able to escape the planet.' FROM games WHERE igdb_id = 17686 ON CONFLICT (game_id, language_code) DO NOTHING;
