INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sairento VR', 'Sairento VR is one of the most popular action VR games in the world and the only one where you get to play a cyber ninja. Perform triple jumps, wall runs, power slides, back flips and slow time down while blasting away at a foe before landing to deliver a lethal strike on another. Kit yourself with katanas, firearms, bows, throwing glaives and legendary relics. Experience the iconic "bullet-time" scenes from The Matrix, blended with the slow-motion mayhem of the Max Payne game series, all while looking and feeling as badass as the Bride from Kill Bill.' FROM games WHERE igdb_id = 30522 ON CONFLICT (game_id, language_code) DO NOTHING;
