INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mhakna Gramura and Fairy Bell', 'Written by the prolific author "Alissyn Rievegh" in her early 20''s, "Mhakna Gramura and Fairy Bell" (Mhakna for short) was her foray into the children''s novel genre and has been a hit classic in the Alliance ever since it''s initial release. Now, the first time ever, the original text has been translated into Japanese and English and art, fully restored by ALICE IN DISSONANCE and Sekai Project.' FROM games WHERE igdb_id = 81009 ON CONFLICT (game_id, language_code) DO NOTHING;
