INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop-Up Pilgrims', 'Floating Cloud God and his devoted pilgrims have a big adventure ahead! Put on your PlaystationVR headset and discover a world of pop-up islands, colorful characters, and deadly demons, all uniquely presented as 2D graphics in a wrap-around 3D space. More than 50 stages curve around the player as they try to lead the pilgrims from platform to platform – left, right, in or out – to take on a cast of lively enemies and find a safe route to the exit.' FROM games WHERE igdb_id = 90094 ON CONFLICT (game_id, language_code) DO NOTHING;
