INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed: Rogue Remastered', 'In addition to running in 4K, Assassin''s Creed Rogue Remastered sports higher-resolution textures and shadows, improved environmental rendering, and new visual effects, making its sprawling wilderness, Arctic icescapes, and bustling version of New York City more striking than ever. The new edition also packs in all of the original''s downloadable content and expansions, including two bonus missions – The Armor of Sir Gunn and The Siege of Fort de Sable – as well as the weapons, outfits, and customization items in the Master Templar and Explorer packs. It also includes a new bonus: Bayek''s legacy outfit from Assassin''s Creed Origins.' FROM games WHERE igdb_id = 81205 ON CONFLICT (game_id, language_code) DO NOTHING;
