INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kolumno', 111641, '2018-11-15', 53, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26ng.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc1e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kolumno', 'Wait for the right moment and make the ball fall through the intricate columns. Does it seem easy for you? It isn’t! Behind its apparent simplicity, Kolumno hides really challenging and fun game mechanics.  Kolumno, as other puzzle games, requires intelligence, planning, and patience, but the challenge doesn’t stop there. It will also test your reflexes with puzzles that will require you to use special abilities such as: stopping mid-air, falling faster, making smaller or breaking the rings that make up the columns.  Don’t let yourself be fooled by its minimalistic style and its relaxing soundtrack, Kolumno is one of the most elegant and challenging games in recent times.  Features:  - 4 different items that expand the complexity of the puzzles.  - 75 levels full of challenges.  - Elegant graphic and sound styles.  - Easy to start, hard to master.' FROM games WHERE igdb_id = 111641 ON CONFLICT (game_id, language_code) DO NOTHING;
