INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trailblazers', 'Trailblazers is a fresh new co-operative racing title with an innovative on-track game mechanic: paint the track, boost on your colour and work as a team to win! Take control of high-speed racers in unique 3v3 team races across a series of colourful circuits. Paint the track as you race, capturing key areas to dynamically change the racing line, then boost on your team''s colour to dominate the race! - True co-operative team racing with a brand new, never-before-seen core mechanic - Exciting high-speed circuit racing with second-to-second strategy that is new to the genre - Play online, either solo or together with split screen buddies' FROM games WHERE igdb_id = 88383 ON CONFLICT (game_id, language_code) DO NOTHING;
