INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('slime-san-superslime-edition', 96019, '2018-06-22', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co275f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aruau.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slime-san: Superslime Edition', '"Slime-san: Superslime Edition includes all three major campaigns as well as some brand new, exclusive levels and features! Mama’s Madness: You’ve been swallowed by a giant worm! Your goal is to platform yourself through its intestines back out its mouth before you get digested! Blackbird’s Kraken: You were about to take a vacation with your family and got eaten whole by a giant Kraken?! Once more you’ll need to jump, slime & slide your way out! Sheeple’s Sequel: Sheeple believes he’s an NPC in a video game and decides to recode himself as the villain! Can you beat his mind-bending levels? Superslime Edition packs an extra 10 exclusive levels where you can play as Grandpa-san himself! It also includes a “Dynamic Colors” feature that alters the game’s color palette to a unique one for each world. Slime-san’s more colorful than ever!"' FROM games WHERE igdb_id = 96019 ON CONFLICT (game_id, language_code) DO NOTHING;
