INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie''s Retreat', 'Zombie''s Retreat is an action RPG involving a young man and his camping retreat. What''s intended to be a bonding experience turns horribly wrong when a sudden evil outbreak spreads across the camp. With very ''strange'' circumstances surrounding this new found threat, it is up to the player to save any and all survivors while attempting to escape in one piece!' FROM games WHERE igdb_id = 127634 ON CONFLICT (game_id, language_code) DO NOTHING;
