INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '9-nine-: Episode 2', '9-nine-: Episode 2 is the second volume in a series of supernatural mystery games, with Episode 2 telling a story centered around Sora Niimi. The entries in the the 9-nine- series share the same setting and world, but each entry focuses on a different heroine. 9-nine- is a tale of the town of Shiromitsugawa, host to mysterious Artifacts and the superpowers they bestow on their Users. A tale of a brother and sister with a close bond, and also a murder mystery where they hunt down the culprit behind a series of supernatural murders. Each game has an independent story that can be enjoyed on its own.' FROM games WHERE igdb_id = 121587 ON CONFLICT (game_id, language_code) DO NOTHING;
