INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Is the Police 2', 'Interpret the law as you see fit in This Is the Police 2, sequel to the acclaimed noir drama This Is the Police! Run the sheriff''s department, manage your cops, investigate, interrogate, and incarcerate. Make tough decisions - and try to keep out of prison yourself – in this story-driven mixture of adventure, strategy, and turn-based tactical combat. Is it a simulation? A management game? A tactical challenge? A visual novel? A puzzle? It''s all of these, and more!' FROM games WHERE igdb_id = 84486 ON CONFLICT (game_id, language_code) DO NOTHING;
