INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ni no Kuni II: Revenant Kingdom', 'The sequel to Ni no Kuni being developed for Windows and PlayStation 4. Players control Evan Pettiwhisker Tildrum, a young king who was usurped from his castle and sets out to reclaim his kingdom. While players can freely navigate Evan throughout the game''s open world, other characters can be controlled during battles against enemies. During these battles, players use magical abilities and elemental creatures known as "Higgledies", which are used to cast spells.' FROM games WHERE igdb_id = 14748 ON CONFLICT (game_id, language_code) DO NOTHING;
