INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('castlevania-rondo-of-blood', 222228, '2018-10-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zoh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar226m.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Rondo of Blood', 'A remaster of Castlevania: Rondo of Blood included in the "Castlevania Requiem" collection. Experience Rondo of Blood remastered to 4K/1080p resolution, with optional rendering options such as image-smoothing. This remaster is based on the English-localization of Rondo of Blood, which was previously released exclusively as part of its remake, Castlevania: The Dracula X Chronicles. Venture through 9 stages featuring hidden levels and alternative routes to save imprisoned villagers as you set out to destroy count Dracula once and for all. Playable characters include Richter Belmont the Vampire Hunter and Maria Renard the master of the 4 celestial beasts.' FROM games WHERE igdb_id = 222228 ON CONFLICT (game_id, language_code) DO NOTHING;
