INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancestors Legacy', 'Ancestors Legacy is a history-inspired, real-time strategy game influenced by historical events in the Middle Ages. The game combines resource management and base building with large-scale, squad-based battles across vast battlefields, all rendered in superb detail with Unreal Engine 4. Experience medieval bloodshed like never before thanks to the cinematic action camera that puts you right in the middle of the battle at the press of a button.' FROM games WHERE igdb_id = 28794 ON CONFLICT (game_id, language_code) DO NOTHING;
