INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atom RPG', 'Atom RPG is a post-apocalyptic indie game, inspired by classic CRPGs: Fallout, Wasteland, System Shock, Deus Ex, Baldur''s Gate and many others. In 1986 both the Soviet Union and the Western Bloc were destroyed in mutual nuclear bombings. You are one of the survivors of the nuclear Holocaust. Your mission - to explore the wild and wondrous world of the Soviet Wasteland. To earn your place under the sun. And to investigate a shadowy conspiracy, aimed at destroying all that is left of life on Earth.' FROM games WHERE igdb_id = 28160 ON CONFLICT (game_id, language_code) DO NOTHING;
