INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rise-of-the-teenage-mutant-ninja-turtles-ninja-run', 146251, '2018-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yj7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8b3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of the Teenage Mutant Ninja Turtles: Ninja Run', 'Rise of the TMNT: Ninja Run is an action game starring the legendary Ninja Turtles. We''re talking about a level-based runner inspired by the Rise of the Teenage Mutant Ninja Turtles show. That''s right, this 2018 comedy revisits the all-time classic Teenage Mutant Ninja Turtles (TMNT or The Ninja Turtles). You get to go on an adventure alongside Raphael, Donatello, Leonardo, and Michaelangelo through 50 different missions in which you have to collect coins in order to stop the New York mutants from gaining control over the city. The game is very similar to other classic games such as Subway Surfers or Temple Run as far as the gameplay goes: your character moves horizontally through different lanes by sliding your finger across the screen. You can also jump and slide under objects by swiping up or down. Each Ninja Turtle includes its own unique attacks, which you can perform by tapping on the screen. There''s even a way to customize them more by using these three elements: costumes, weapons, and skills. Earn these unlockables by advancing through the different levels, or by playing with a roulette (but it''ll cost a pretty significant amount of coins). With your earnings, you can also level up your characters. Rise of the TMNT: Ninja Run is an incredible videogame that combines endless runners and New York''s Ninja Turtles. Shout Cowabunga at the top of your lungs and submerge yourself in a comics universe with the game''s eye-catching style.' FROM games WHERE igdb_id = 146251 ON CONFLICT (game_id, language_code) DO NOTHING;
