INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Way Remastered', '"A remastered version of an award-winning puzzle platformer. The Way Remastered tells a story about a member of space explorers team who lost his beloved and cannot accept her death. During one of his expeditions he discovers ancient writings that testify the existence of a method for obtaining eternal life. Hoping to get his beloved back, he decides to return to the alien planet. However, the planet hides many secrets and dangers that he must face. A story-based puzzle platformer with stunning graphics and soundtrack made by Panu Talus."' FROM games WHERE igdb_id = 96202 ON CONFLICT (game_id, language_code) DO NOTHING;
