INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('luckless-seven', 9758, '2018-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26qr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhul.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luckless Seven', 'Luckless Seven is the story of Mark Vesco’s coming of age. Once an inspired youngster, Mark finds himself living a listless, dutiful existence just two years out of high school. When a group of old friends contacts Mark about reuniting with them, the stars align to allow him to join his old friends in a nationwide competitive tournament.  Take control of Mark as he and six friends set out to compete in Arithia’s most popular game, Ekosi. This fast and fun card game is inspired by KOTOR’s Pazaak, and the stakes couldn’t be higher. With a little experience, money, and luck, take Mark from a modest amateur to an Ekosi champion!  Which card to play won’t be the only difficult choice for Mark, though. Along his journey, Mark will have to make several decisions that will challenge him morally, ethically, and socially. More than just a card game, Luckless Seven invites you to take control of the whole person. Who will Mark be on his quest for glory?' FROM games WHERE igdb_id = 9758 ON CONFLICT (game_id, language_code) DO NOTHING;
