INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timespinner', 'Timespinner is a 2D metroidvania platformer about a young woman who travels through time to destroy the empire that killed her family. At its heart, the game is a child of the great pixelated classics of the SNES and PS1 age. From the rich story worlds of Star Ocean, the expansive gothic castle to explore in Castlevania: Symphony of the Night, and the tight gameplay of Megaman X, Timespinner seeks to weave all of these elements into one amazing game.' FROM games WHERE igdb_id = 28952 ON CONFLICT (game_id, language_code) DO NOTHING;
