INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Underhero', 'Underhero is a 2D side-scroller RPG adventure game with timing-based combat. It tells an intriguing and mysterious story, full of silly characters brimming with personality, quirky dialogue, and lots of weird humor. Inspired by Paper Mario games and RPGs in general, it tells the story of a world where the chosen hero has failed and an underling of the main villain takes his place as the new “hero”. Join the magical hilt Elizabeth the IV and the little Masked Kid, as they travel the world to restore Elizabeth’s long lost power, so they can defeat the tyrannical Mr. Stitches and save the world once and for all!' FROM games WHERE igdb_id = 36652 ON CONFLICT (game_id, language_code) DO NOTHING;
