INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hunt-down-the-freeman', 89147, '2018-02-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dmpygywa10p928pkimnp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arobf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunt Down the Freeman', 'It''s time to tell the story of the villain. Hunt Down The Freeman takes you into a journey like no one has before. Witness the pain of the villain firsthand with over 14 hour gameplay, over 40 levels, immersive gameplay, cinematic cutscenes and an over an hour long, heart touching OST. The player picks up the Machete of H.E.C.U Sergeant Mitchell, who finds himself in a hospital during alien invasion so called 7 Hour War. Mitchell is thrust into a battle of survival and is forced to face challenges to survive. This marine has to use all of his training, both with firearms and thinking tactically, to parkouring across the levels. Mitchell has to manage his inventory with over twenty-six unique weapons and gadgets, find the best way to get the job done, and do whatever it takes for his own survival.' FROM games WHERE igdb_id = 89147 ON CONFLICT (game_id, language_code) DO NOTHING;
