INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Space Waifu: Fantasy', 'A new incarnation of the deep space waifu series! A casual strip ''em up action game! Travel to the fantastical kingdom of Hentalia and do some cloth damage in giant girls! Meet lots of waifus from fantastical races, all waiting to meet you! Be a hero! Save the Kingdom! And slay some… monsters!' FROM games WHERE igdb_id = 102167 ON CONFLICT (game_id, language_code) DO NOTHING;
