INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Office Quest', 'The Office Quest is a casual point & click adventure game for those who cannot stay in the office any longer, full of visual humor, puzzles, riddles, and earnest adults wearing fluffy onesies because why not. You have a boring job, clicking the same key on the same keyboard at the same desk every day of every week. Then one day something strange and magical happens, and you really, really need to discover what''s going on – and for that, you need to slip away of your post and leave the grey abyss they call the office…' FROM games WHERE igdb_id = 99521 ON CONFLICT (game_id, language_code) DO NOTHING;
