INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Smash Bros. Ultimate', 'Legendary game worlds and fighters collide in the ultimate showdown—a new entry in the Super Smash Bros. series for the Nintendo Switch system! New fighters, like Inkling from the Splatoon series and Ridley from the Metroid series, make their Super Smash Bros. series debut alongside every Super Smash Bros. fighter in the series…EVER! Faster combat, new items, new attacks, new defensive options, and more will keep the battle raging whether you’re at home or on the go.' FROM games WHERE igdb_id = 90101 ON CONFLICT (game_id, language_code) DO NOTHING;
