INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Construction Co', 'From the participation-award-winning comic creators of Dungeon Construction Co. (whose moms love them very much), and a guy who made a game once with cats and tacos in it, comes the okayest game you’ve played since you installed [insert RPG title]** on your grandma’s heart monitor.' FROM games WHERE igdb_id = 96196 ON CONFLICT (game_id, language_code) DO NOTHING;
