INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Triglav', 'The tower of Triglav consisting of 50+ floors. Go for the top floor where the princess is captured, by searching for keys that open the doors to the next floor, by solving puzzles, and by monster hunting. In this unique world created by richly detailed retro pixel art, create your own unique character by combining items of over 2,500 types. This is a smartphone version of the hack and slash type RPG released as an indie web game in 2002 and has been played by over 500,000 players. Many audio and visual effects, such as sound effects and music, have been added which were not included in the original version.' FROM games WHERE igdb_id = 148004 ON CONFLICT (game_id, language_code) DO NOTHING;
