INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Detector Island: A Metal Detecting Game', 'You walk around on an island digging up random bits of metal objects. Most of the time you''ll find trash, but the most rewarding feeling is when you find treasure. These objects earn a varying number of points, depending on what the object comes out as, which you can use to buy skins or upgrades for your detector. Listen to calming music as you take in the island''s unique scenery. What can you dig up?' FROM games WHERE igdb_id = 106005 ON CONFLICT (game_id, language_code) DO NOTHING;
