INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starlink: Battle for Atlas', 'Starlink: Battle for Atlas is an all-new action-adventure game developed by Ubisoft Toronto. This deep, open-world space saga features Smart Building Technology empowering players to assemble and customize real-world physical starships. Each part attached to the starship appears instantly in-game and players can experiment with different pilot abilities, weapon types, and status effects and unleash devastating combos upon their enemies.' FROM games WHERE igdb_id = 37066 ON CONFLICT (game_id, language_code) DO NOTHING;
