INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Gardens Between', 'The Gardens Between is a surreal puzzle adventure through memory, moments and time that follows best friends, Arina and Frendt, as they fall into a mysterious world of beautiful garden islands. The player can traverse back and forwards in time to discover each garden''s secrets and, along the way, reveal a story about friendship, childhood and growing up.' FROM games WHERE igdb_id = 27324 ON CONFLICT (game_id, language_code) DO NOTHING;
