INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unravel Two', 'Unravel Two is the sequel to the 2015 puzzle platforming game Unravel. In the game there are two Yarny''s (made out of yarn) which can be controlled by one player, though the game can also be played in co-op. Together the Yarny''s explore area''s and solve the puzzles within them.' FROM games WHERE igdb_id = 19241 ON CONFLICT (game_id, language_code) DO NOTHING;
