INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('six-ages-ride-like-the-wind', 57335, '2018-06-28', 88, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co296a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nqvdsnzky7srp1drcixn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Six Ages: Ride like the Wind', '"Life between myths. Clans, cows, choices.  The spiritual successor to King of Dragon Pass, Six Ages combines interactive stories and turn-based strategy. Your small clan’s survival depends on its relations with the warring gods and their followers. Play involves actions such as improving pastures, exploration, trading with your neighbors, and raiding. You can even travel to the Otherworld to visit your gods. You also need to deal with crises ranging from marauding dinosaurs to diplomatic requests to illicit love. Your choices have a politico-economic impact, but some consequences might not be obvious for decades.  It’s set in Glorantha (the world of the games RuneQuest, HeroQuest, and 13th Age), where the laws of physics are subordinate to the whims of the gods and spirits.  Six Ages is immensely replayable, thanks to over 400 interactive scenes with multiple outcomes. Short episodes and automatic saving mean you can play even when you only have a minute or two. The built-in saga writes down the story for you. And advisors with distinctive personalities help you track your cows."' FROM games WHERE igdb_id = 57335 ON CONFLICT (game_id, language_code) DO NOTHING;
