INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Super Squad', 'Animal Super Squad is a physics-based game that lets you play a chicken riding a toilet on wheels, or a sloth with a propeller on its butt, speeding through a world full of traps and bananas. You can also create your own maps to infuriate your friends with, and ticking off our friends is what we all live for anyway.' FROM games WHERE igdb_id = 74598 ON CONFLICT (game_id, language_code) DO NOTHING;
