INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Old School Musical', 'Old School Musical is a retro rhythm game that will make you fall back in your childhood. Tib and Rob are the heroes of an epic and completely crazy adventure that will make them cross numerous worlds searching for the source of all bugs. With more than 20 original levels, a story mode, some hidden minigames and much more, Old School Musical offers a richer experience than most rhythm games.' FROM games WHERE igdb_id = 51408 ON CONFLICT (game_id, language_code) DO NOTHING;
