INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-child-lebensborn', 83852, '2018-05-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/z2ruwjgzcqroxuhb4ykb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcoc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Child: Lebensborn', 'A story-driven nurture game. Help the child of an enemy in a post-war society. WHAT HAPPENS WHEN THE WAR ENDS? Does hatred just go away? My Child Lebensborn is a story-driven nurture game - a dark tamagotchi - letting you experience the fates of Children Born of War. Take care of Karin and Klaus and help them survive in a post-war society. Find out what happened to their parents and try to find a better future. My Child lebensborn combines genre and theme in a unique way. You take part in the journey of a child, through a significant time. - Balance meagre resources and emotional needs - Influence the child''s personality and views - Make tough choices' FROM games WHERE igdb_id = 83852 ON CONFLICT (game_id, language_code) DO NOTHING;
