INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wreckfest', 'Wreckfest is a racing video game developed by Bugbear Entertainment and published by THQ Nordic. It features demolition derbies and traditional races with a strong emphasis on vehicular damage and realistic physics. The game includes various modes such as career, multiplayer, and custom events. Released in 2018, Wreckfest is notable for its detailed destruction modelling and the strategic depth required in vehicle customisation and handling.' FROM games WHERE igdb_id = 3772 ON CONFLICT (game_id, language_code) DO NOTHING;
