INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('word-puzzle-game', 86726, '2018-01-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ajywcdczp00wju6g4x0l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/essbshgnbjej0n6ujj5w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Puzzle Game', 'Join thousands of players who exercise their brains every day with the best crossword game now available for Mac. Word Puzzle Game is a fun and engaging game. A Word Puzzle Game is a word puzzle that normally takes the form of a square or a rectangular grid of white and black shaded squares. The goal is to fill the white squares with letters, forming words or phrases, by solving clues that lead to the answers. In languages that are written left-to-right, the answer words and phrases are placed in the grid from left to right and from top to bottom. The shaded squares are used to separate the words or phrases.
