INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snack-world-the-dungeon-crawl-gold', 28830, '2018-04-12', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vxp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar424k.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snack World: The Dungeon Crawl - Gold', 'An enhanced version of The Snack World: TreJarers, an action RPG developed by Level-5, released in 2017 for the Nintendo 3DS. "Crawl through randomly-generated dungeons in this roguelike RPG, delving deeper and deeper, besting brutal bosses, and hunting down rare loot. Prepare your equipment in town for the challenges that await! Head out to explore caves, woods, and other dangerous locales. Team up to topple tenacious tyrants! - Da~rling! Lookin'' go~od! You are the crawler of your own dungeon! Create your own character to captain the colorful cast in this clichéd chronicle of...comeuppance?! - Nail Your Adventurer Aesthetic! High fantasy and high tech collide in this familiar fantasy RPG with a modern twist for gamers of all generations! - Juggle Your Jaras in the Heat of Battle! Master the use of equipment called jaras that you can swap in & out on the fly to efficiently eliminate your enemies! - Lookin'' Like a Snack! Collect summonable companions called snacks and use their abilities to turn the tide of battle! What? That''s, like, never been done before! Right? - Dungeon Crawlers, Grab That Booty! May the RNG gods look kindly upon you as you clear quests to collect ever-better booty!"' FROM games WHERE igdb_id = 28830 ON CONFLICT (game_id, language_code) DO NOTHING;
