INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bolsomito', 'Bolsomito was a 2D beat ''em up where you control a character that resembles the then Brazilian presidential candidate, Jair Bolsonaro, and needs to "defeat the communistic evils and be the hero that will free the nation from misery by facing many kinds of enemies that intend to establish a criminal ideological dictatorship in the country." The game was delisted after the Public Ministry of the Federal District and Territories opened an investigation against the developers and requested Valve Corporation to cease all sales and "identify and qualify those responsible for BS Studios".' FROM games WHERE igdb_id = 107496 ON CONFLICT (game_id, language_code) DO NOTHING;
