INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Final Fantasy: Maxima', 'World of Final Fantasy: Maxima is the powered up version of WORLD OF FINAL FANTASY which was originally released in October 2016. CAPTURE, CUSTOMISE AND EVOLVE! Embark on a magical journey with siblings Reynn and Lann as they explore the vast land of Grymoire to rediscover their past and save the future. With charming and stylised visuals, players will capture, customise and evolve iconic creatures by stacking them to form adorable yet strategic monster towers. The memorable legends of FINAL FANTASY come to life in this imaginative, colourful world as an epic story fit for the smallest of heroes unfolds.' FROM games WHERE igdb_id = 109461 ON CONFLICT (game_id, language_code) DO NOTHING;
