INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Déraciné', '"Déraciné is a brand new story adventure created by the renowned Bloodborne developer, FromSoftware, available exclusively on PSVR. As a spirit summoned by a young girl in a secluded boarding school, the player must prove its existence and build a unique bond with the students through clever interactions. As the mystery of the story unfolds, the spirit must use its ability to manipulate the forces of life and time to change the fate of the pupils."' FROM games WHERE igdb_id = 103332 ON CONFLICT (game_id, language_code) DO NOTHING;
