INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Retimed', 'Retimed is a local multiplayer arena shooter for 2-4 players. When a player is in danger, time slows down and a time bubble is created around the player. Now there is enough time to react and try to dodge the deadly projectiles. These time bubbles generate exciting alternations between fast-paced movement and tension-filled slowmotion moments.' FROM games WHERE igdb_id = 76921 ON CONFLICT (game_id, language_code) DO NOTHING;
