INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword Art Online: Fatal Bullet', 'Sword Art Online: Fatal Bullet is a Third Person Shooter Role-Playing Game (TPSRPG), scheduled to be released on February 8, 2018 on the PlayStation 4, XBox One, as well as Personal Computers (PCs) via Steam. The game is being developed by Dimps, based on Unreal Engine 4, and will be set in Gun Gale Online. It will be the first Sword Art Online TPSRPG and the first Sword Art Online game on the XBox One platform.' FROM games WHERE igdb_id = 36515 ON CONFLICT (game_id, language_code) DO NOTHING;
