INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zigzag-fidget', 82529, '2018-01-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wxqhoo2xyribcrmfzksq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bbpppjhe6i6ytbimvjmp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZigZag Fidget', 'It''s a simple straight forward endless game that puts you in control of a fidget stick which is mostly controlled by some crazy laws of physics but other than that, you swipe to move the stick forward and tap at the right moment to make it stop. The game requires impeccable timing and concentration and is a major challenge even for veterans.  The game''s difficulty is deep embedded in its core. Everything has been built around it ensuring that players will love accepting this challenge.' FROM games WHERE igdb_id = 82529 ON CONFLICT (game_id, language_code) DO NOTHING;
