INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tasty Planet Forever', 'This is the biggest Tasty Planet game ever. There are hundreds of different entities to eat and well over 150 levels. The scale of some of the levels is enormous; in one level you''ll grow all the way from the size of a subatomic particle to the size of the universe.' FROM games WHERE igdb_id = 110538 ON CONFLICT (game_id, language_code) DO NOTHING;
