INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fox-n-forests', 21961, '2018-05-17', 69, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co216m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc9n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fox n Forests', '"Fox n Forests is a 2D 16-Bit style action platformer with adventure and puzzle elements, empowering you to switch seasons on the fly! Set within a mystic forest and its surroundings, Fox n Forests is a stunning fable offering pixel perfect Retrotainment and rewarding challenges! The game is inspired by the glorious days of 16-Bit and all time classics like Super Ghouls ’n Ghosts, Wonder Boy in Monster World and ActRaiser 2 as well as the Castlevania and Zelda series. You play as Rick the Fox and your weapon is a magic melee crossbow that can not only be used for ranged and close up combat, but empowers you to seamlessly switch between 2 seasons per level, completely changing the whole environment and resulting in amazing secrets, tricky skill tests and thriving exploration. Pixel perfect platforming, screen filling bosses, rich bonus levels, powerful potions, bags of loot, stuffed shops, clever backtracking, challenging skill tests, a magic melee crossbow to shoot and slash enemies, upgradeable shots, not 4 but 5 seasons to explore, stunning 16-Bit pixel art, a catchy chip tunes soundtrack and tons of humorous retro charm combined with the luxuries of modern game design will make Fox n Forests a worthy revival of games from the Golden Age. Easy to learn, difficult to master, impossible to not fall in love with!"' FROM games WHERE igdb_id = 21961 ON CONFLICT (game_id, language_code) DO NOTHING;
