INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nun Massacre', 'A letter has arrived at your house under mysterious circumstances... your daughter has fallen ill at her boarding school. As you make a trip to pick her up, a storm blows in and the road is blocked. You continue on foot through the woods and all hell soon breaks loose... Hide from the PSYCHOPATHIC nun at all costs! She hungers for BLOOD and you are the next course! Nothing could prepare you for a NUN MASSACRE! Terrifying ps1 style stealth horror.' FROM games WHERE igdb_id = 112215 ON CONFLICT (game_id, language_code) DO NOTHING;
