INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forsaken Remastered', '"Developed by Probe Entertainment and Iguana Entertainment and first released in 1998 for PlayStation, PC and Nintendo 64, Forsaken was a vision of a dystopian future where science has gone out of control. Scavengers from all over the known worlds have come to Earth to loot the remains of the technology that can found in underground tunnels. But beware! You must fight your way past automated defenses and the scum of the universe to find the treasures hidden on each level. As you mount your hoverbike, be prepared for deadly combat. You are going to quickly learn that the future is... Forsaken!"' FROM games WHERE igdb_id = 106102 ON CONFLICT (game_id, language_code) DO NOTHING;
