INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scythe: Digital Edition', 'Scythe is a board game set in an alternate-history 1920s period. It is a time of farming and war, broken hearts and rusted gears, innovation and valor. In Scythe, each player represents a fallen leader attempting to restore their honor and lead their faction to power in Eastern Europa. Players conquer territory, enlist new recruits, reap resources, gain villagers, build structures, and activate monstrous mechs.' FROM games WHERE igdb_id = 81124 ON CONFLICT (game_id, language_code) DO NOTHING;
