INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grip', 'Inspired by the Rollcage games of 1999 and 2000, Grip is a new IP for a new generation. A return to the hardcore combat racer, bristling with heavy weapons and packing ferocious speed, the game is an intense, sensory feast. Harnessing the awesome potential of Epic''s Unreal Engine 4, GRIP will take you back to your nostalgic past, while simultaneously propelling you into a kick-ass future.' FROM games WHERE igdb_id = 18452 ON CONFLICT (game_id, language_code) DO NOTHING;
