INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Liberation Dx2', 'A free-to-play mobile rpg developed by SEGA based on the Atlus series Shin Megami Tensei. "Shin Megami Tensei: Liberation Dx2 is a turn-based role-playing game coming to Android and iOS mobile devices. Summon, fuse, and raise your own demons to fight by your side. The game will feature sweet AR functionalities and intense multiplayer feats!"' FROM games WHERE igdb_id = 57019 ON CONFLICT (game_id, language_code) DO NOTHING;
