INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MachiaVillain', 'Machiavillain is an evil mansion management and strategy game, inspired by Dungeon Keeper, Prison Architect and all the horror movie clichés! Build your own manor, raise your monsters, set up your traps, and exterminate your victims. But to gain reputation you''ll have to slay by the horror movie rules!' FROM games WHERE igdb_id = 27497 ON CONFLICT (game_id, language_code) DO NOTHING;
