INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battlecry', 7210, '2018-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p45rfvmbcc3zml7vsly9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tubbmfyrhq2jrqdte19g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BattleCry', 'Battlecry amplifies team-based combat by combining visceral brutality and competitive multiplayer action to create a new gameplay experience. Choose your warrior - each with a meaningfully distinct suite of attacks and abilities - from one of several factions from diverse parts of the world. With strategy, brutal attacks, and unique weapons, fight for power and glory in 32-player battles across the WarZones. This is the life of a warrior, and victory is yours for the taking. Following a cataclysmic world war at the dawn of the 20th century, the most powerful Empires left standing came together to ban gun powder under The Black Powder Treaty. The short peace that followed gave birth to the Pansophic Revolution – a golden age of industrial manufacturing and design. As technology advanced, old tensions reignited and soon the world faced the scourge of war once more. Fueled by technological Pansophic advancements, the face of warfare has changed. All disagreements are settled head-on by elite teams of chosen warriors from all over the world, with each member specializing in either high-tech ranged gadgetry or sophisticated melee weapons. Trained and bred for battle, they meet each other in sanctioned WarZones to face off for their share of glory.' FROM games WHERE igdb_id = 7210 ON CONFLICT (game_id, language_code) DO NOTHING;
