INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vegas Infinite by PokerStars', 'PokerStars presents Vegas Infinite, a world of entertainment with no limits. Leap into virtual reality or, coming soon, sit back and play on PC with no headset required. Take on the house at action-packed blackjack and roulette. Light up the dice with your friends at craps. Choose from a dazzling selection of slots, and challenge real opponents in cash, Spin & Go, Sit & Go, and multi-table tournament poker. From luxury casino floors, private suites, and galactic space stations to soaring skylines and exclusive rooftop escapes, lose yourself in stunning environments while you play. Be yourself with a giant collection of customizable accessories and apparel, and add a touch of magic to your gameplay with an endless supply of props. Your seat is open.' FROM games WHERE igdb_id = 110104 ON CONFLICT (game_id, language_code) DO NOTHING;
