INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squad 44', 'Formerly known as Post Scriptum, Squad 44 is the most authentic WW2 first-person shooter, featuring 20 large-scale battlefields, upwards of 80 realistic WW2 weapons, and over 50 true-to-life vehicles. You must prioritize communication, coordination, and teamwork to snatch victory from the jaws of defeat. Experience real WW2 campaigns, such as the liberation of the Netherlands and the Battle of Normandy. The war stretched across the farms, villages, and cities of Europe, and whether you’re jumping out of a plane, arriving by sea, or storming the battlefield in a tank, you’ll need to group up with your squad before taking on the enemy.' FROM games WHERE igdb_id = 81141 ON CONFLICT (game_id, language_code) DO NOTHING;
