INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Liar Princess and the Blind Prince', 'The Liar Princess and the Blind Prince follows the tale of two lonely hearts brought together through a mutal misunderstanding. In it, you control the wolf, disguised as a princess, who guides the blind prince through a perilous forest in search of the witch capable of restoring his sight. The forest is home to a number of hostile creatures intent on ending your journey prematurely, as well as hazardous traps that put the prince in danger.' FROM games WHERE igdb_id = 82370 ON CONFLICT (game_id, language_code) DO NOTHING;
