INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucah: Born of a Dream', 'A top-down hack-and-slash where Lucah must fight to reclaim their identity from the grasp of the Nightmare monsters that inhabit the dream-like land. Lucah: Born of a Dream features a hand-drawn surrealist artstyle and contains heavy themes relating to organized religion, queerness and suppression of one''s identity through indoctrination.' FROM games WHERE igdb_id = 99120 ON CONFLICT (game_id, language_code) DO NOTHING;
