INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-persistence', 37282, '2018-06-24', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25mr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbur.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Persistence', '"The Persistence is First Person Stealth Horror exclusively for PS4 & PSVR. The Persistence is procedurally generated. Every time you die and a new character is awoken by IRIS, the layout of the ship has changed. Every life will play out differently, with different enemies to face, items to find and power-ups to collect. Survival requires you to be stealthy and VR is the perfect match for this. Sneaking around and hiding behind cover; it''s second nature in VR to just lean round or peek over cover to gain the advantage Your friends can also help out by connecting to the game with their phone or tablet and hacking into the ship''s computer. Once in the ship''s system, players get to control doors, freeze or distract enemies, disable traps and find hidden items to scavenge for the VR player. Be aware though, sometimes the tablet player gets rewarded if you die, do you trust your friends?"' FROM games WHERE igdb_id = 37282 ON CONFLICT (game_id, language_code) DO NOTHING;
