INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble It Up!', 'Roll, bounce, and boost your way from skillful start to frame-perfect finish in Marble It Up! - the next generation of marble-rolling platformer. Chase the records of your friends and the world''s best players through intricate, beautiful, mind-bending levels… Get Ready to Marble It Up! Marble It Up! Classic is an indefinitely preserved snapshot of the game before Marble It Up! Ultra released. Classic features less featured customization, no multiplayer, and a lower level count overall, yet retains the exact physics as they were at-launch. It is not directly purchasable, but buying Ultra will grant the owner free access to Classic on Steam and Switch.' FROM games WHERE igdb_id = 107302 ON CONFLICT (game_id, language_code) DO NOTHING;
