INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pode', '"Pode is the story of a little rock helping a fallen star find its way home. As they travel through the insides of a mysterious and magical mountain, Bulder and Glo breathe life into an ancient sleeping world and explore the ruins of a long lost civilization with their unique talents and abilities. Only by helping each other can these unlikely adventure companions solve the ancient puzzles that open the secret passageways up the caverns of Mount Fjellheim. Pode is a co-op puzzle exploration game built around the themes of friendship and cooperation, with a strong emphasis on positive actions, relaxing atmosphere and beautiful art inspired by Norwegian culture. "' FROM games WHERE igdb_id = 94054 ON CONFLICT (game_id, language_code) DO NOTHING;
