INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('do-not-feed-the-monkeys', 52014, '2018-10-23', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28xk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard9d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Do Not Feed the Monkeys', 'Do Not Feed the Monkeys is a digital voyeur simulator: a narrative-driven game where you invade the privacy of dozens of strangers and witness their most intimate moments, while you struggle to keep up to date with paying the rent and putting some food on the table. You are the newest member of the “The Primate Observation Club” -and of course it is not the wildlife conservation society the name would suggest. It is a front for a shadowy group that watches others through surveillance cameras and compromised webcams. Tired of your ramshackle apartment, dull existence and boring jobs, you’re accepted into the exclusive organization, so you can pry into the privacy of the “caged monkeys” as they go about their lives. The game lets you to Browse social networks, wikis, websites, newspapers, online stores and chat lounges to gather information about the “monkeys” you are charged to spy. The club urges you to not interfere with those observed (to not “feed the monkeys”). But then, what will you do? Will you intercede in the name of justice? Sabotage their dreams? Or will you just sit idly by while the world burns? Whatever you do (or don’t do) will have consequences!' FROM games WHERE igdb_id = 52014 ON CONFLICT (game_id, language_code) DO NOTHING;
