INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrono Trigger', 'As the definitive version of Chrono Trigger, not only have the controls been updated, the graphics and sound have also been revamped to make your adventure even more fun and enjoyable to play. To complete your journey, also included is the mysterious ‘Dimensional Vortex’ dungeon and the forgotten ‘Lost Sanctum’ dungeon. Meet the challenges presented to you and long-lost secrets may be revealed...' FROM games WHERE igdb_id = 206320 ON CONFLICT (game_id, language_code) DO NOTHING;
