INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mark-of-the-ninja-remastered', 94969, '2018-10-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob89e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zsmhbyupal9uqqucuq0y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mark of the Ninja: Remastered', 'In Mark of the Ninja, you''ll know what it is to truly be a ninja. You must be silent, agile and clever to outwit your opponents in a world of gorgeous scenery and flowing animation. Marked with cursed tattoos giving you heightened senses, every situation presents you with options. Will you be an unknown, invisible ghost, or a brutal, silent assassin? Upgrade new tools and techniques that suit your playstyle and complete optional objectives to unlock entirely new ways to approach the game. Finish the main story to unlock a New Game Plus mode with even more options and challenges.' FROM games WHERE igdb_id = 94969 ON CONFLICT (game_id, language_code) DO NOTHING;
