INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('unknown-fate', 31866, '2018-09-06', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co249o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5oo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unknown Fate', 'Unknown Fate is an enigmatic story-driven action adventure set in a surreal world full of mind-twisting puzzles and bizarre creatures. Set off on an amazing journey through Unknown Fate, a strongly story-driven first-person adventure with many puzzles to solve and enemies to beat. Become Richard, who suddenly passes seamlessly from the real world into a surreal universe. You’ll encounter strange characters, unfamiliar artifacts and scenes resembling Richard’s former life, of which he has lost all memory. Yet, he knows that this is not where he is supposed to be. The world he has come to inhabit is strange and distant. He feels the urge to find out more about this surreal universe and the creatures inhabiting it, in order to find a way out – out and back to his real self, his real life that he knows he has yet to fully recall. With no way back and a strong urge for answers beating in your temples, you push on, striving to get a grip on the odd difficulties surrounding you, eagerly awaiting the moment your mind will become untangled when the thread of your journey finally unravels all the way.' FROM games WHERE igdb_id = 31866 ON CONFLICT (game_id, language_code) DO NOTHING;
