INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('assassins-creed-rebellion', 41030, '2018-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1hg7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/m8sgfg27mlhkrl9bqp30.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed: Rebellion', 'Join Ezio, Aguilar, Shao Jun and other legendary Assassins in new adventures! Build your own Brotherhood and infiltrate the Templars’ strongholds in the first Strategy-RPG of the Assassin''s Creed universe." Assassin’s Creed Rebellion is a completely new free-to-play standalone mobile game based on the lore of the Assassin’s Creed saga. Set during the Spanish Inquisition, Assassin’s Creed Rebellion will feature famous Assassins such as the beloved Ezio, Aguilar or Shao Jun and other legendary Assassins who will help them build a new Brotherhood. In this RPG-Strategy mobile game, players will be able to build, manage and develop their own Brotherhood by recruiting, collecting and improving skills of their Assassins while completing thrilling missions to infiltrate the Templar’s strongholds and defeat their plans.' FROM games WHERE igdb_id = 41030 ON CONFLICT (game_id, language_code) DO NOTHING;
