INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iro Hero', 'In a world where humans are used as power supplies, only one man has the will to change it all! Iro Hero is a vertical shoot ’em up with beautiful pixel art graphics inspired by many old-school classics. Staged across 9 action-packed levels, Iro Hero features a unique and fresh four-color polarity system, with interactive elements, puzzles, color zones, weapon upgrades and special skills to unlock.' FROM games WHERE igdb_id = 76090 ON CONFLICT (game_id, language_code) DO NOTHING;
