INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infliction', 'Infliction is a story driven first person physiological horror experience. Set in a regular suburban home, the story is told over alternating time periods spanning 13 years. Through environmental storytelling, Infliction tackles taboo subject matter. While you''re discovering what has happened over the last 13 years, you''re being stalked by an evil entity. Can you learn enough to vanquish the evil that lies within this family home or will you become a victim?' FROM games WHERE igdb_id = 55282 ON CONFLICT (game_id, language_code) DO NOTHING;
