INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('overdriven-reloaded-special-edition', 53438, '2018-02-09', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/a0kcucwbtg5zxjjmgwut.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbjf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overdriven Reloaded: Special Edition', 'Overdriven Reloaded: Special Edition The HD shoot'' em up: vertical, fast & fun ! Relive the pleasures of arcade shoot''em ups in plenty of Game-Modes, from 1 to 4 Players in Local Co-op. Destroy Huge Bosses and dodge thousand of bullets ... It''s time to save the universe one more time ! 7 Modes : - Story (with 4 Difficulties: EASY - NORMAL - HARD- NIGHTMARE), - Arcade, - Manic (no healthbar for player), - The Line, - 7 Challenges, - 56 Puzzle-Maps ( Color-Reflex Mode / A Match 3 with bullets !), and a Boss-Rush ! - 2 spaceships ( + 1 unlockable), - 50 alien artifacts to collect, - 10 space cows to find, - 70 Xbox Live achievements, - Dedicated Leaderboards for all modes and difficulties, - A great original instrumental rock soundtrack !' FROM games WHERE igdb_id = 53438 ON CONFLICT (game_id, language_code) DO NOTHING;
