INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dawn of the Breakers', 'Dawn of the Breakers was an anime-inspired 3D action game built around an extensive single-player campaign in which you''ll battle against a variety of foes, ranging from eccentric super-powered villains, to massive and truly fearsome monsters. Make new allies and uncover treacherous plots as you progress through the main scenario! Defeat the impending menace, the mysterious "Ghouls"!' FROM games WHERE igdb_id = 106972 ON CONFLICT (game_id, language_code) DO NOTHING;
