INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('will-hero', 92116, '2018-03-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gy4nryg6dzgnipbs5pwv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/a9kojjuitwekvvjtgupw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Will Hero', 'Will Hero is an arcade, action, platformer and rogue-like in one game. This is an exciting adventure, in which you can dive in any place and at any time! When Princess gets in trouble, a REAL hero turns into unstoppable maul and makes his way with bombs, kicks and axe. Make a tap to perform a dash, evade or attack. Master a sword, push your way through with hefty kicks, bombs, throwing knives and axes.  Improve weapons by increasing their lethal force. Build a high tower, open a lot of devastating combat spells. Find dozens of helmets for your hero, among which there are brutal helmets: knight, prince, crusader, viking, dragon; and cute: Cat, Dog, Unicorn, Panda, Raccoon, Chicken, Hog and many, many others. Explore dungeons and different game worlds. Find rare and legendary chests containing unique helmets. Will Hero is not just a timekiller, it''s an exciting arcade, action and platformer, which can be played with only one finger. The game works without the Internet, it is enough to download and it will blow your mind. Play anywhere and anytime! Compete with friends and become a hero!' FROM games WHERE igdb_id = 92116 ON CONFLICT (game_id, language_code) DO NOTHING;
