INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Ultra Kogal', 'Super Ultra Kogal tells the story of Sadako, a Japanese schoolgirl, karate expert & junk food enthusiast. After getting beating up and robbed after school by a Yakuza affiliated gang of Kogals, she goes into a rampage thru Tokyo''s most famous districts while hunting down each of her attackers.  Inspired by classic fighting puzzle games, as a player of Super Ultra Kogal, you will be able to fight your way thru iconic Tokyo''s districts like Akihabara & Shibuya while facing archetypal enemies, including perverted Salarymen, Mecha Otakus and Gothic Lolitas.' FROM games WHERE igdb_id = 16751 ON CONFLICT (game_id, language_code) DO NOTHING;
