INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fathom', 10966, '2018-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/qny5tkvg9mchh41x3eiu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/e8ln4bgut36udukrn1fy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fathom', 'FATHOM is a fast paced action-strategy submarine combat game for the PC, where you’ll need quick reflexes, clever piloting skills, and tactical leadership to survive. Bringing a unique mixture of First-Person-Shooter (FPS) and Real-Time-Strategy (RTS) genres, FATHOM is a multi-player focused game that offers a variety of modes that support competitive (1v1 and team) play, as well as cooperative play. Take control of a Deep Submergence Vehicle (DSV) and prepare for battle. Use beacons to call down structures from the sea surface and layout your base of operations to begin your campaign. Construct warships and command your fleet into the heart of your enemy’s base! Set up blockades of deployable turrets and mines to defend strategic locations from your enemies. Call to the sea surface for depth charge bombardments from above or bring huge capital ships to bear in an all-out epic war beneath the waves!' FROM games WHERE igdb_id = 10966 ON CONFLICT (game_id, language_code) DO NOTHING;
