INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('timothy-vs-the-aliens', 84108, '2018-01-31', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3de5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxnn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timothy vs. the Aliens', 'Timothy vs. the Aliens is an open-world platformer, and adventure video game where a gangster will defend his black & white city from an invasion of full-colored aliens. The game takes place in Little Fish City, an open and large city that can be freely explored and hides many secrets and missions. This is a city full of platforms, and going through it won''t be just walking from one point to another. In addition, you will be able to explore the whole city by car, using any of the vehicles that appear in the game. In Timothy vs. the Aliens you will also find many moments of action in ambushes by aliens, as well as lots of puzzles to find items, help other characters, and access blocked or hidden places.' FROM games WHERE igdb_id = 84108 ON CONFLICT (game_id, language_code) DO NOTHING;
