INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circle Empires', 'Circle Empires is a fresh take on the RTS genre, featuring a fast-paced approach to conquering the world. The Circle Empires universe is made of interconnected circles, each containing loot to plunder and foes to defeat. You are the god-like leader of your tiny kingdom, hungry for power. Use your skills to hunt down increasingly powerful enemies and expand your empire. The game world changes every time you play - no two games are the same. And... you can grow pumpkins!' FROM games WHERE igdb_id = 104937 ON CONFLICT (game_id, language_code) DO NOTHING;
