INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Looney Tunes World of Mayhem', 'Join Bugs Bunny, Daffy Duck, Marvin the Martian and all the classic toons to build the greatest “Toon Team” in Looney Tunes World of Mayhem! Collect cartoon characters like Tweety Bird, Taz, Road Runner and more to wage wacky battles in a vibrant Looney Tunes World. Collect your favorite characters and discover their unique and hilarious fighting abilities. Characters from Road Runner and Wile E. Coyote to Sylvester and Tweety to Porky Pig each have unique abilities and hilarious attacks. Collect all the classic Looney Tunes cartoon characters in this epic action RPG.' FROM games WHERE igdb_id = 97314 ON CONFLICT (game_id, language_code) DO NOTHING;
