INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout 76', 'Bethesda Game Studios welcome you to Fallout 76. Twenty-five years after the bombs fall you and your fellow Vault Dwellers, chosen from the nation’s best and brightest, emerge into post-nuclear America on Reclamation Day, 2102. Play solo or join together as you explore, quest, build, and triumph against the wasteland’s greatest threats. Explore a vast wasteland, devastated by nuclear war, in this open-world multiplayer addition to the Fallout story. Experience the largest, most dynamic world ever created in the legendary Fallout universe.' FROM games WHERE igdb_id = 103020 ON CONFLICT (game_id, language_code) DO NOTHING;
