INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA 19: Champions Edition', 'Experience the world’s most prestigious club competition with the addition of the UEFA Champions League. The legendary tournament is woven into every mode in FIFA 19, introducing brand new ways to play. This edition includes:  - Up to 20 FIFA Ultimate Team Jumbo Premium Gold Packs (one per week for 20 weeks)  - Play from September 25 with three days early access  - UEFA Champions League Gold Player Pick (Choose one of five 80 to 83 rated gold players from qualified teams)  - Cristiano Ronaldo and Neymar Jr. loan items for seven FUT matches  - Special Edition FUT kits designed by FIFA soundtrack artists' FROM games WHERE igdb_id = 103377 ON CONFLICT (game_id, language_code) DO NOTHING;
