INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beacon', 18200, '2018-04-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23y8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2wfj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beacon', 'Beacon is a sci-fi themed Action Roguelike. Played as a top-down shooter, you must fight your way through a randomly generated hostile world, all the while trying to locate your emergency distress beacon and escape the planet into which your ship has crashed. While you’re making your way through these areas you’ll not only find weapons and items to help you; You’ll also be collecting DNA from the enemies you defeat. Then, when you inevitably die, you’re given the opportunity to combine the DNA you’ve collected to your own, granting you different stats and potentially gameplay-altering physical mutations for your next run. Beacon aims to create a bridge between fast, frenetic action and long-term strategy, where your actions can be felt and built upon hours down the line.' FROM games WHERE igdb_id = 18200 ON CONFLICT (game_id, language_code) DO NOTHING;
