INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cardinal Chains', 'Cardinal Chains is a minimalist puzzle game centering on the concept of non-decreasing sequences.  Each puzzle begins with a monochrome grid of numbers, plus a few colored cells marked with an X. Starting at these cells, you must link up numbers in non-decreasing order until the whole grid is filled with color.' FROM games WHERE igdb_id = 96221 ON CONFLICT (game_id, language_code) DO NOTHING;
