INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Warfare 2', 'Dungeon Warfare 2 is the definitive sequel to Dungeon Warfare, a challenging tower defense strategy game where you become a dungeon lord to defend your dungeons with the deadliest of traps and insidious contraptions against greedy adventurers and wannabe heroes.  Game Features  - Physics-enabled tower defense mayhem  - 33 unique traps with 8 unique traits for each trap  - More than 30 unique enemies, each with a special trait  - More than 60 handcrafted levels + an infinite number of procedurally generated dungeons  - 5+ boss battles  - Progression with experience providing passive upgrades for the traps as well as skill points  - Three skill trees with 11 skills on each tree  - Equipment system with more than 30 unique items  - Mix your own difficulty by combining difficulty mode runes for more challenge & reward  - Endless mode  - Environmental Hazards' FROM games WHERE igdb_id = 102273 ON CONFLICT (game_id, language_code) DO NOTHING;
