INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('signal-simulator', 99625, '2018-04-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1th6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjev.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Signal Simulator', 'Game inspired by SETI. Take the role of a scientist to find an extraterrestrial signal .Control massive Radio Antennas by using interactive control in your Observatory. Detect , download and decode unknown or story telling signals. Manage and Maintain an electrical system to improve your systems and make it more efficient. Detect more signals, earn credits and upgrade your systems to improve their performance.  Find story telling signals that will give you more data and will tell the story of explorers out in the space.  GAME FEATURES  Scan and analyze anomalies in the sky  Set the right signal frequency to detect a signal coordinates  Set coordinates and control your Radio Antennas using interactive game controls  Locate and detect signals from outer space  Download Raw Data from the signals and Decode it  Earn credits based on the data you have downloaded and upgrade your systems  Upgrade and improve your systems  Electrical System based on day night circle  Maintain solar panels, clean them and improve the recharge rate of the system  Calibrate your antennas  Weather that affects your systems  Database system where all your unique signals will be saved  Server system, maintain antenna and observatory servers using terminal like commands.  Tracking system  Temperature system that will affect the temperature of you system  Terminal like control, where you can rotate your antennas, reboot server , detect signals  Mysterious things' FROM games WHERE igdb_id = 99625 ON CONFLICT (game_id, language_code) DO NOTHING;
