INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indie Pogo', '"Indie Pogo is a platform brawler game for 2-4 players about bouncing, ricocheting, and pogoing your friends into oblivion! It’s sort of like if we replaced the cast of Smash Bros. with 30+ indie fighters and gave them all trampolines to fight on. Inspired by games like Super Smash Bros, Legend of the Mystical Ninja, and League of Legends, we are developing a competitive yet quirky game that is easy to learn yet difficult to master. After collaborating with over 50 studios across 15 different countries, we''re striving to create the ultimate indie crossover!"' FROM games WHERE igdb_id = 67203 ON CONFLICT (game_id, language_code) DO NOTHING;
