INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('friday-the-13th-killer-puzzle', 83891, '2018-01-19', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kef.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arddu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Friday the 13th: Killer Puzzle', '"From the makers of Slayaway Camp—the award-winning “Bloodiest Puzzle Game Ever”—comes an even more frightening puzzler starring one of horror’s most iconic killers. Now you can go behind the hockey mask of Jason Voorhees on his mission to murder unfortunate campers at Crystal Lake and beyond. Players control Jason by sliding him around an isometric puzzle level to attack his victims, either directly with a variety of weapons, or indirectly, by frightening them into environmental hazards like campfires, bear traps, and woodchippers. Gruesome reflex-based “Kill Scenes” punctuate the puzzling as you progress through multiple episodes, from classic campgrounds to more exotic locations such as Manhattan, abandoned amusement parks, supermax prisons, beach resorts, outer space and more."' FROM games WHERE igdb_id = 83891 ON CONFLICT (game_id, language_code) DO NOTHING;
