INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('city-of-the-shroud', 18354, '2018-08-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vi7hykqq7ds4dhu67ay1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1blr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City of the Shroud', 'City of the Shroud is a tactical RPG with a twist - battles take place in a real-time, combo-based combat system where you unleash special moves, build powerful combos, and outmaneuver your opponent.  Join the live, player-driven story as it unfolds in a sprawling world, where bitter rivalries battle for control of a city descending into civil war. As you play, your choices, and the choices of every player, will create a living world of shifting alliances as you race to uncover the truth before it''s too late.  -Real-time, combo-based battle system: think on your feet and chain together your attacks to defeat your opponents  -The story is a living episodic campaign: every player''s actions impact how the story unfolds for the entire community.  -4 episodes: each episode is crafted based on the cumulative influence of every player''s choices and actions from the previous episodes.  -Written by multiple chart-topping independent author Moira Katson  -Online PVP multiplayer  -Deep combo and stat system lets you customize your character to suit your playstyle  -Mod support: customize the appearance of your units in battle  -A distinctive world, beautifully realized in 2D and 3D' FROM games WHERE igdb_id = 18354 ON CONFLICT (game_id, language_code) DO NOTHING;
