INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skater XL', 'Skater XL is the evolution of skateboarding games and moves the genre towards expressive, physics-based gameplay. Players will experience unparalleled board control and responsiveness while they skate legendary real-world skate spots. With ground-breaking and intuitive controls, skateboarding in a video game has never felt more authentic, fluid, and responsive.' FROM games WHERE igdb_id = 113175 ON CONFLICT (game_id, language_code) DO NOTHING;
