INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PixelJunk Monsters 2', 'Get ready to experience the next generation of real-time tower defense gameplay in the globally acclaimed PixelJunk Monsters series! The spirit of the forest, Tikiman, is in trouble. An army of mysterious monsters has invaded his peaceful forest! Repel the fire and fury of your assaulting foes! Build towers within the woods and level them up to vanquish the invaders! Protect the Chibis, the future of the Tiki tribe!' FROM games WHERE igdb_id = 95386 ON CONFLICT (game_id, language_code) DO NOTHING;
