INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fracter', '"Set in a mysterious labyrinth of glowing black architecture, Fracter follows a veiled young hero who has set out on a perilous quest to dispel the darkness within. Players must explore this realm of shadows, discover secrets hidden in the dark and outsmart ominous creatures while solving each meticulously designed puzzle using their only force against darkness: light. Fracter features dramatic landscapes in shades of gray, an eerie ambient soundtrack and a poetic, self-reflective narrative that leads players on an emotional journey to restore light to a darkened world."' FROM games WHERE igdb_id = 101167 ON CONFLICT (game_id, language_code) DO NOTHING;
