INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ok/Normal', 'Ok/Normal is a short, experimental third-person horror experience, inspired by early 3D console games of the 90''s. Journey through a dark, disjointed, dreamlike dimension with your cloud companion! Remember a good diet, take your medicine, and you should be fine!' FROM games WHERE igdb_id = 101635 ON CONFLICT (game_id, language_code) DO NOTHING;
