INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro the Dragon', 'The first game in the Spyro series has been completely remade from the ground up. It stars the title character, a young purple dragon named Spyro, and his dragonfly friend, Sparx, who must journey across the Dragon Kingdom to defeat Gnasty Gnorc, who has overtaken the 5 dragon Homeworlds by trapping the other dragons in crystal and turning their hoard of gems into an army of minions.' FROM games WHERE igdb_id = 142213 ON CONFLICT (game_id, language_code) DO NOTHING;
