INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro: Year of the Dragon', 'The Dragon Realms are celebrating the ‘Year of the Dragon’ when a mysterious cloaked figure emerges to steal all the Dragon Eggs. Under the spell of the evil Sorceress, an army of Rhynocs is now guarding the helpless eggs in the Forgotten Realms. With new and old friends, Spyro is on a quest to recover the lost eggs, defeat the Rhynoc army and stop the evil Sorceress.' FROM games WHERE igdb_id = 142243 ON CONFLICT (game_id, language_code) DO NOTHING;
