INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reigns: Game of Thrones', 'Through the fiery visions of Melisandre, claim the Iron Throne as Cersei Lannister, Jon Snow, Daenerys Targaryen, and more to carefully navigate the complex relationships and hostile factions of the Seven Kingdoms. Employ ruthless tactics to outwit political rivals and wield impervious charm on your fickle bannerman. Maintain the balance and favor of the people to extend your reign and maybe, one day, survive the horrors of the coming winter.' FROM games WHERE igdb_id = 107237 ON CONFLICT (game_id, language_code) DO NOTHING;
