INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heaven Will Be Mine', 'Heaven Will Be Mine is a queer science fiction mecha visual novel from the creators of queer cult horror visual novel We Know The Devil, about joyriding mecha, kissing your enemies, and fighting gravity’s pull. Follow three women piloting giant robots in the last days of an alternate 1980s space program fighting for humanity’s future—or ditching their jobs to make out with each other instead.' FROM games WHERE igdb_id = 69482 ON CONFLICT (game_id, language_code) DO NOTHING;
