INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robo Puzzle Smash', 'Robo Puzzle Smash is an intensely addictive competitive puzzle game that will test your wits and skill against your opponent in a high-energy, block bashing brawl with a twist! Drop the blocks and rotate your field to match colored blocks together and set up combos. When the moment is right, use a Breaker to smash the blocks to send them to your enemy!' FROM games WHERE igdb_id = 88023 ON CONFLICT (game_id, language_code) DO NOTHING;
