INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Attack Helicopter Dating Simulator', 'As a helicopter, your daily activities may include, morning maintenance, aerial attack runs, and delivering hell-fire missiles on noncombatants for democracy. Or you know, dating other helicopters. It is a visual novel after all...' FROM games WHERE igdb_id = 105952 ON CONFLICT (game_id, language_code) DO NOTHING;
