INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cultist-simulator', 26878, '2018-05-31', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co288g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3zn3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cultist Simulator', 'Seize forbidden treasures. Summon alien gods. Feed on your disciples. Cultist Simulator is a game of apocalypse and yearning from Alexis Kennedy, creator of Fallen London and Sunless Sea. Play as a seeker after unholy mysteries, in a 1920s-themed setting of hidden gods and secret histories. Perhaps you''re looking for knowledge, or power, or beauty, or revenge. Perhaps you just want the colours beneath the skin of the world. In this roguelike narrative card game, what you find may transform you forever. Every choice you make, from moment to moment, doesn''t just advance the narrative - it also shapes it. Become a scholar of the unseen arts. Search your dreams for sanity-twisting rituals. Craft tools and summon spirits. Indoctrinate innocents. Seize your place as the herald of a new age.' FROM games WHERE igdb_id = 26878 ON CONFLICT (game_id, language_code) DO NOTHING;
