INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Slater', 'Get ready to kill low-life drug dealers, notorious crime bosses and anyone who stands in your way as you seek revenge for your father''s murder. Use stealth-based tactics to get the upper hand on your enemies and take them out. Think your enemies as puzzle pieces. How do you get past the guards? Who do you kill and how? Think carefully before you make your move or you are the one ending up dead.' FROM games WHERE igdb_id = 104815 ON CONFLICT (game_id, language_code) DO NOTHING;
