INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Salt', 'Salt is an ocean based adventure and exploration game set in a infinite procedurally generated world. Experience pure freedom to play the way you want as you sail across a vast ocean and explore huge islands in your search for adventure. During your travels you will fight pirates, bosses and other creatures, complete quests, customize your ships, hunt wildlife, sail huge waves, loot and craft items and resources, and discover mysterious places and secrets throughout the world.' FROM games WHERE igdb_id = 17929 ON CONFLICT (game_id, language_code) DO NOTHING;
