INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megalith', '"Megalith is an action-packed hero shooter that transforms you into a titan, letting you use your massive size and firepower to compete with others in a quest to become a god. Immersed in the conflict of an ancient world, you will need to use a combination of teamwork and skill to survive. Fight for supremacy on the fields of battle using free locomotion, strategy, and destructible environments. Define your own style of combat by customizing your abilities so that you can vanquish your foes and push your disciples to victory."' FROM games WHERE igdb_id = 75246 ON CONFLICT (game_id, language_code) DO NOTHING;
