INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kobold-chapter-i', 112055, '2018-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28yy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5pjg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kobold: Chapter I', 'Kobold is a new kind of horror experience that blurs the line between cinema and VR gaming. Step into the shoes of an urban explorer investigating the mysterious case of a missing boy. Pick up your flashlight and discover the secrets of an abandoned villa in the middle of a dark forest in Germany. Immerse yourself in true, cinematic realism, explore an interactive universe, pick up clues and dare to venture deeper into a mystical world where your actions can have grave consequences. With its intensely realistic visuals captured with photogrammetry, free movement and intuitive interactions, Kobold is a unique room scale VR experience that will entice and terrify... A trans-media experience, KOBOLD is accompanied by a short film that can be viewed before entering the VR experience. The short film serves as an introduction into the world and characters and tells the backstory of the missing boy and his family. It is available to watch for free on the KOBOLD website. The player then puts on a VR headset and steps into the story, breaking into the abandoned villa, gathering clues, solving a mystery and entering a dark, mythical underworld inspired by European folklore and pagan mythology. In order to make the transition from film to VR as immersive as possible, the entire villa (which is a real location in Brandenburg, Germany) and its surroundings were meticulously scanned with photogrammetry. Actors were also 3D scanned and brought to life in VR using motion capture and advanced facial capture technology. AAA graphics from an indie studio, with character and level design, compelling gameplay and intuitive interactivity designed from the ground up for the Oculus Rift and HTC Vive.' FROM games WHERE igdb_id = 112055 ON CONFLICT (game_id, language_code) DO NOTHING;
