INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danger Zone 2', 'Danger Zone 2 takes the crash testing action out of the Test Area and onto real public roads. A high speed driving game featuring speed, traffic and crashes, Danger Zone 2 lets players loose onto the Freeways of the USA, the Motorways of the UK and the Autovias of Spain. Using advanced real world physics and the power of Unreal Engine, Danger Zone 2 lets players ‘crash for cash’ and compete against each other to cause the most chaos on the road.' FROM games WHERE igdb_id = 104231 ON CONFLICT (game_id, language_code) DO NOTHING;
