INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sushi Striker: The Way of Sushido', '"The ultimate food fight! In the fast-paced world of conveyor-belt sushi fighting, match colored plates and types of sushi to hurl tall stacks of plates at your opponent. The more matches you make, the taller the plate stack and the stronger your attacks will be. Defend your homeland from invading enemies in this puzzling action game so more people can enjoy delicious sushi in peace. May the best sushi samurai reign supreme!"' FROM games WHERE igdb_id = 37179 ON CONFLICT (game_id, language_code) DO NOTHING;
