INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Another Sight', 'Created with heart, culture and character, ANOTHER SIGHT is the story of Kit and Hodge. Whilst exploring the London Underground during its construction in 1899, Kit, a bold teenager is caught in a tunnel collapse. When Kit wakes up, her sight is gone, and she’s left helpless in the dark world below London. Hodge, a mysterious cat finds Kit, and becomes her companion on a journey through a surreal fantasy adventure, influenced by Neil Gaiman’s Neverwhere.' FROM games WHERE igdb_id = 90146 ON CONFLICT (game_id, language_code) DO NOTHING;
