INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('god-wars-the-complete-legend', 86681, '2018-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1huv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ara8e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'God Wars: The Complete Legend', 'A definitive edition of the game including all previous DLC, a new scenario that will also be available as DLC for the original game, an option to speed up battles, the use of 8 units in battle instead of 6, unlocked level/skill limits, multiple endings, as well as a new character. "The legend is reborn! God Wars: The Complete Legend is an expanded release of God Wars: Future Past, a tactical RPG that explores the untold history of Japan through folklore and tactical combat. Experience the traditional stories of Japan’s origin through the lens of three warring nations through gameplay and beautiful anime cinematics, engage in deep tactical combat with a myriad of character classes, and explore the lives of heroes who made their mark by fighting against the fate set out before them."' FROM games WHERE igdb_id = 86681 ON CONFLICT (game_id, language_code) DO NOTHING;
