INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Tennis Aces', 'A new Mario Tennis game is bringing a new level of skill and competition to Nintendo Switch. Mario steps onto the court in classy tennis garb for intense rallies against a variety of characters in full-blown tennis battles. New wrinkles in tennis gameplay will challenge your ability to read an opponent''s position and stroke to determine which shot will give you the advantage. And this time the game adds the first story mode since the Mario Tennis game on Game Boy Advance, offering a new flavor of tennis gameplay, with a variety of missions, boss battles and more' FROM games WHERE igdb_id = 81145 ON CONFLICT (game_id, language_code) DO NOTHING;
