INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gris', 'Gris is a 2D platformer developed by Nomada Studio and published by Devolver Digital. It is a visually striking game that follows the journey of a young woman named Gris as she navigates a world of grief and loss. The game features no dialogue, relying on its hand-painted art style, evocative music, and environmental storytelling to convey its themes. Gameplay involves exploration, light platforming, and puzzle-solving, with Gris gaining new abilities as the story progresses. It received critical acclaim for its artistic design and emotional depth.' FROM games WHERE igdb_id = 22917 ON CONFLICT (game_id, language_code) DO NOTHING;
