INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'InnerSpace', 'InnerSpace is an exploration flying game set in a world where physics are inverted. Take the role of an unnamed Cartographer to explore the Inverse, a collection of worlds where the Ancients once lived. Collect relics, and encounter each world''s mythical demigod, in a quest to discover the secrets of the Inverse, its history, and its future.' FROM games WHERE igdb_id = 35844 ON CONFLICT (game_id, language_code) DO NOTHING;
