INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('summer-pockets', 87682, '2018-06-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co276f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqit.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Pockets', 'Summer Pockets is set on an isolated, rural and peaceful island on the Seto Inland Sea called Torishirojima, which has a population of about 2,000 people. The protagonist is Hairi Takahara, a young man not native to the island. Hairi grew up in an urban setting, but after an unpleasant incident, he uses the recent death of his grandmother as an excuse to come to the island to take care of her estate sale. Once there, he gets to know four girls who are the focus of the story. They include Shiroha Naruse, who forgot her summer vacation: Ao Sorakado, who is pursuing the legends of the island. Kamome Kushima, a high-class girl looking for a pirate ship. and Tsumugi Wenders, a younger girl trying to find herself.' FROM games WHERE igdb_id = 87682 ON CONFLICT (game_id, language_code) DO NOTHING;
