INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Creepy Road', 'Our game tells you a story about Flint Trucker''s adventures in crazy freakin'' world. Flint is a brutal man with a shotgun who just try to reach home to save his love. But the car got broken, way to home is blocked by thousands of creepy animals and mad men. What is left to do, except of take the gun and discover himself what the hell is going on!' FROM games WHERE igdb_id = 86255 ON CONFLICT (game_id, language_code) DO NOTHING;
