INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mary-skelter-2', 89548, '2018-07-12', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1s6d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aas277lbjscngot8wavv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mary Skelter 2', 'What must you sacrifice to escape fate? Find out in this nightmarish dungeon-crawling RPG! The Nightmare continues in Mary Skelter 2! In this first-person dungeon crawler, play as fairy tale-inspired characters called Blood Maidens, each with deeply customizable character-specific classes. Balance between power and madness in turn-based battles with a blood-fueled transformation system, and escape a living prison while indestructible Nightmares give chase in real time. This game includes a full remake of the original Mary Skelter: Nightmares with additional story content as a free DLC. It is recommended that players finish Mary Skelter 2 before playing through the remake. The gameplay system revisions made in Mary Skelter 2 are also reflected in the remake of Mary Skelter: Nightmares.' FROM games WHERE igdb_id = 89548 ON CONFLICT (game_id, language_code) DO NOTHING;
