INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disgaea 1 Complete', 'A version of Disgaea: Hour of Darkness, including the added content in Afternoon of Darkness and Disgaea PC, was released for Nintendo Switch and PlayStation 4 on October 9, 2018, retitled as Disgaea 1 Complete. Some elements of the game were updated, including adding new higher resolution sprites in the same style as Disgaea 5, changing character art images with the Disgaea 5 artstyle, as well as retroactively replacing some generic humanoid and monster classes that did not appear since Disgaea: Hour of Darkness with classes that do appear in later games in the series.' FROM games WHERE igdb_id = 82373 ON CONFLICT (game_id, language_code) DO NOTHING;
