INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pool Panic', 'Pool Panic is the world’s least realistic pool simulator. Play as a mischievous, and dare we say, oblivious cue ball in a giant game of pool that sprawls across a colorful cartoon overworld with more than 100 levels. Explore jungles, deserts, carnivals, cities and more while knocking around a peculiar cast of billiard balls, most of which won’t appreciate being pocketed.' FROM games WHERE igdb_id = 95028 ON CONFLICT (game_id, language_code) DO NOTHING;
