INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RockShot', 'RockShot is a free-to-play dynamic third-person shooter combining traditional online shooter gameplay with innovative elements. Explore a massive arsenal of firearms or rock the battlefield with crazy melee weapons and deadly airstrikes! The game was taken offline through loss of the game''s servers when Gameforge stopped supporting it in September 2018. It still has a page on steam though the game cannot be launched.' FROM games WHERE igdb_id = 74731 ON CONFLICT (game_id, language_code) DO NOTHING;
