INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life & Debt: A Real Life Simulator', 'Life & Debt: A Real Life Simulator is a 2D pixel art life management simulator. Life & Debt focuses on the beginnings of new home ownership after moving out of your parents'' house. You will have to maintain your finances and cashflow while having a really bad shopping addiction. Will you be able to furnish your house with everything or will you end up hoarding clocks or waterbottles?' FROM games WHERE igdb_id = 88036 ON CONFLICT (game_id, language_code) DO NOTHING;
