INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Full Metal Furies', 'Defend the free world from tyrannical titans in FULL METAL FURIES – a team-based brawler where cooperation is the key to victory. An abstruse allegorical action adventure about atonement, allusions, and alliteration awaits all at an alternate age around Athens’ ashes. FULL METAL FURIES will challenge you to think like a team, and to rethink what a brawler could be.' FROM games WHERE igdb_id = 27343 ON CONFLICT (game_id, language_code) DO NOTHING;
