INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Firewall Zero Hour', 'Firewall: Zero Hour is a 4-on-4 tactical shooter designed for PlayStation VR. Teamwork is everything in this intense squad-based shooter – put on your PlayStation VR headset, gather an arsenal of equipment, and prepare for blistering combat. Choose from 12 experienced mercenaries and familiarize yourself with upgradeable weapons. Will you lock and load with the attacking squadron, tasked to obtain valuable data in a hostile environment? Or will you be on the frontlines of the defending team, making sure the data is kept out of enemy hands by any means necessary?' FROM games WHERE igdb_id = 76966 ON CONFLICT (game_id, language_code) DO NOTHING;
