INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Our Asias', 'From the co-creator of Anodyne. In this surreal, PSX-like adventure, learn someone''s secrets and experiences by exploring their mind. Control Yuito as you explore his estranged and dying father''s "Memory World" - what surreal and supernatural things will you find?' FROM games WHERE igdb_id = 68216 ON CONFLICT (game_id, language_code) DO NOTHING;
