INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Keep in Mind: Remastered', 'Keep in Mind follows Jonas, a tormented alcoholic whose life is falling apart. One night, he awakens to a shadowy mirror world where beasts lurk and the stars don''t shine. Lost and scared, Jonas must face all those twisted beasts if he ever wishes to return home and learn the truth about his darkness. Keep in Mind: Remastered takes the Game Jolt version of the game and revamps it with a new engine, bug fixes, and brand new professionally composed soundtrack.' FROM games WHERE igdb_id = 87757 ON CONFLICT (game_id, language_code) DO NOTHING;
