INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wandersong', 'Wandersong takes you on a whimsical, musical journey across the globe. Eons ago, the goddess Eya put the universe into motion with her music--now, as she does every epoch or so, she''s going to sing a new song and reset existence. You play as a lowly bard tasked with finding the pieces of a mysterious melody called the Earthsong, which is said to be able to preserve the planet. Use your singing to help characters, solve puzzles, and save the world!' FROM games WHERE igdb_id = 23851 ON CONFLICT (game_id, language_code) DO NOTHING;
