INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('phantom-doctrine--1', 55121, '2018-08-14', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/oaov1veblnyapulbcfdb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/van6vmfbwnpfxabbydyx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantom Doctrine', 'Set in 1983 during the Cold War, Phantom Doctrine is an alternate history thriller in which players lead The Cabal, a secret organization dedicated to fighting a global conspiracy committed to controlling the world by pitting world leaders and nations against one another. Deception is the great equalizer as players will have to operate from the shadows to exploit every vulnerability - ruthlessly interrogate and brainwash enemies and allies alike to create double agents, saboteurs or unwitting collaborators. Develop and defend your base of operations, recruit agents from the world’s many factions, and research new tech to give your operatives the advantage. Campaign missions deliver sprawling tactical encounters that revolve around two key pillars: stealth and explosive, all-out attacks. Your team of operatives can be deployed into the ﬁeld either fully armed or disguised as civilians, allowing them to inﬁltrate dangerous areas undetected at the expense of heavy weapons and armor. Decode and analyze your way through immersive investigations to expose far-reaching conspiracies and elusive targets. Delve into the oppressive dark corners of the volatile 1980s with atmospheric visuals and an unnerving soundtrack by award-winning composer Marcin Przybylowicz of The Witcher 3: Wild Hunt fame.' FROM games WHERE igdb_id = 55121 ON CONFLICT (game_id, language_code) DO NOTHING;
