INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mashinky', 'Mashinky is a transport strategy game about trains. The goal is to create your own transport empire on a procedurally generated map. It’s a unique blend of realistic graphics combined with an isometric construction mode and board game-like rules.' FROM games WHERE igdb_id = 55590 ON CONFLICT (game_id, language_code) DO NOTHING;
