INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saboteur!', 'A classic retro hit. SimFabric in cooperation with Clive Townsend prepared a special remastered version of Saboteur! A game originally created in 1985 by Clive Townsend for the 8-bit computer ZX Spectrum. The game received the prestigious "The Crash Smash" award. After 33 years, SimFabric studio in cooperation with Clive Townsend prepared a special remastered version of Saboteur!' FROM games WHERE igdb_id = 112670 ON CONFLICT (game_id, language_code) DO NOTHING;
