INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('baldis-basics-in-education-and-learning', 102832, '2018-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ako.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16f5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baldi''s Basics in Education and Learning', 'This game is not what it seems... Inspired by creepy/bad edutainment games from the 90s, Baldi''s Basics is a meta horror game that''s really weird, with no real educational value to be found. The goal of the game is to collect seven notebooks, and then escape the school, but that''s easier said than done! You''ll need to learn all the ins-and-outs of the game to come up with a winning strategy and avoid being caught by Baldi. Learning how to use Baldi''s friends to your advantage, wisely managing the items found throughout the school, and memorizing the layout of Baldi''s school are all keys to success!' FROM games WHERE igdb_id = 102832 ON CONFLICT (game_id, language_code) DO NOTHING;
