INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forgotton Anne', 'Forgotton Anne is a 2d cinematic adventure game combining puzzle platforming with adventure game elements. You play as Anne, the enforcer keeping order in the Forgotton Realm, as she sets out to squash a rebellion that might prevent her master, Bonku, and herself from returning to the human world. The World of Forgotton Anne: Imagine a place where everything that is lost and forgotten goes; old toys, letters, single socks. The Forgotten Realm is a magical world inhabited by Forgotlings, creatures composed of mislaid objects longing to be remembered again.' FROM games WHERE igdb_id = 24426 ON CONFLICT (game_id, language_code) DO NOTHING;
