INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dasher 3D', 'Dasher 3D is a top down shooter with time-freezing. And it''s controlled with only one button as it''s a part of Feldo''s 1-Button Jam! You are the Dasher, a lonely sprite that shoots and well... dashes around. A group of angry bots have attacked you in huge numbers, but you can do something that they can''t: Control the time! As you dash around and stop, time freezes and lets you decide to either shoot, or to dash again.' FROM games WHERE igdb_id = 179423 ON CONFLICT (game_id, language_code) DO NOTHING;
