INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blast-off', 'Blast-off is a hardcore jumper, where your alter ego will be a ball of anti-matter seeking to leave our Universe. Anti-matter is extremely difficult to exist in our universe, because when it contact with matter it annihilates. This forces the hero to reach super-fast speed to break through the space-time and break through the limit, where he will find peace in the void.' FROM games WHERE igdb_id = 34767 ON CONFLICT (game_id, language_code) DO NOTHING;
