INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-neptunia-rpg', 97255, '2018-12-20', 54, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r3b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nndnupbpbcyf04ujsyri.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Neptunia RPG', 'There was once a primitive form of entertainment software that ruled the world: 2D games. In one of infinite dimensions, the world of Gamindustri exists... a world where 2D games reign supreme. An organization fiercely devoted to these games rules over this vibrant world. They are known as Bombyx Mori and their devotion comes with a heavy price. Citizens of Gamindustri are forced to offer 2D games to Bombyx Mori as taxes. Those who dare to use new technologies or create games that don’t meet their standards risk being banished to the Trial Grounds. It is in this Gamindustri, a dark world with no real future in sight, that a girl wakes from her sleep. Her name is Neptune, and with a strange book in hand, she sets off on the journey of a Hero.' FROM games WHERE igdb_id = 97255 ON CONFLICT (game_id, language_code) DO NOTHING;
