INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Identity V', 'Identity V is an asymmetrical multiplayer horror computer game developed and published by NetEase company. It was released in July 2018 for mobile devices. It is free to download in App Store, Google Play and PC. Five players participate in single matches. One of them is tasked with eliminating the other four before they complete their objectives.' FROM games WHERE igdb_id = 105512 ON CONFLICT (game_id, language_code) DO NOTHING;
