INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('casey-powell-lacrosse-18', 96477, '2018-04-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3mwv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aro7g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casey Powell Lacrosse 18', 'Casey Powell Lacrosse 18 offers sports fans a dynamic, fast, and challenging experience, with all the excitement, speed, and scoring of real-life lacrosse, including a completely reworked series of faceoff, shot, stick and dodging controls. It also features enhanced AI that responds to the complex 6v6 tactics of lacrosse. New motion capture animations for everything from faceoffs and shooting to post-goal celebrations add even further realism to the game. New to Casey Powell Lacrosse 18 is the ability to create custom stadiums and logos for your team. On top of that, Lacrosse 18 features comprehensive player and team creators, allowing you to put yourself and your team right into the thick of the biggest competitions of all.' FROM games WHERE igdb_id = 96477 ON CONFLICT (game_id, language_code) DO NOTHING;
