INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Quest 2', 'Dark Quest 2 is a turn based RPG inspired by legendary board game Hero Quest. The game features a party based system where you control a group of heroes, an isometric hand-drawn art style, dice based mechanics for all computations - (it rolls dice to determine an outcome) and much more.   Each map is designed to take you through an adventure that will test your party''s strength, courage and sanity as you go deeper and deeper into the castle in search for the chambers of the evil sorcerer.' FROM games WHERE igdb_id = 27487 ON CONFLICT (game_id, language_code) DO NOTHING;
