INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nickelodeon Kart Racers', 'Hit the Slime-filled race tracks with Nickelodeon Kart Racers! Select a racer from one of your favorite Nickelodeon series, including SpongeBob, Patrick, and Sandy from SpongeBob SquarePants, Leonardo, Raphael, Michelangelo, and Donatello from Teenage Mutant Ninja Turtles, Arnold and Helga from Hey Arnold!, & Angelica, Tommy and Reptar from Rugrats. Race your friends in up to 4-player local multiplayer or check out the Battle Arena for a variety of challenges.' FROM games WHERE igdb_id = 106109 ON CONFLICT (game_id, language_code) DO NOTHING;
