INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathgarden: Bloodharvest', 'Deathgarden: Bloodharvest finds players in a dark and divided future. Only those deemed worthy are granted entrance to the Enclave, an opulent safe haven, while the rest are damned to almost certain death in the slums. The only gateway between these two worlds is The Bloodharvest, a twisted trial of violence that takes place in arenas known as Deathgardens.' FROM games WHERE igdb_id = 119923 ON CONFLICT (game_id, language_code) DO NOTHING;
