INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mercury Man', '"The Mercury Man is a sci-fi game in the TRPG genre with adventure elements. In this game you will be in the mercury hunter''s shoes. "Mercuries" are people who have subjected themselves to an illegal medical procedure for the sake of curing all diseases. The Mercury Man organically combines a staid point-and-click adventure and tactical fights, a thoughtful gameplay and a fascinating atmospheric plot. As the events unfold, you will be able to gather a complete picture of gloomy world of the future."' FROM games WHERE igdb_id = 80879 ON CONFLICT (game_id, language_code) DO NOTHING;
