INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild West Online', '"Wild West Online" is a emergent systems-driven, open world, Wild West-themed action MMO built from the ground up for PC and featuring world exploration, resource gathering, PvP combat, PvE missions and much, much more. Your actions decide if you''ll be a hero, a villain or something else entirely, where you choose if you want to follow the law of the land or throw the good book out the window. But dig deeper and you might start to suspect there''s more going on here than just lawmakers and lawbreakers - underneath the surface this west is even wilder than meets the eye.' FROM games WHERE igdb_id = 29139 ON CONFLICT (game_id, language_code) DO NOTHING;
