INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crisis on the Planet of the Apes VR', '"Five years since its outbreak, the Simian Flu has wiped out half of humanity and left other primates...evolved. Now at the crossroads of two species’ destinies, you are an ape with advanced intelligence, captured and held prisoner in a heavily guarded scientific facility as mankind desperately searches for a cure. Your mission: confront human aggression as you climb, jump and shoot through the chaos of an apocalyptic world to escape with your fellow apes and return home to Caesar."' FROM games WHERE igdb_id = 89552 ON CONFLICT (game_id, language_code) DO NOTHING;
