INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Radical Heights', '"Welcome to RADICAL HEIGHTS, a free *X-TREME Early Access* BATTLE ROYALE shooter. Partake in high-stakes battle royale gunplay in a sunny SoCal dome as contestants drive-by on BMX bikes or stalk other contestants from the shadows in search for weapons and prizes...but also CASH that you can bank - win or lose! Whether you spend that cash on righteous customization in your personal prize room or pull it from an ATM to purchase weapons early in the next game -- building a wealth of cash is as important as taking down the competition in this irreverent 80s-themed action game show where everyone wants to be rich and famous!"' FROM games WHERE igdb_id = 96239 ON CONFLICT (game_id, language_code) DO NOTHING;
