INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Way Out', 'From the creators of Brothers: A Tale of Two Sons comes A Way Out, an exclusively co-op adventure where you play the role of one of two prisoners making their daring escape from prison. What begins as a thrilling breakout quickly turns into an unpredictable, emotional adventure unlike anything seen or played before. A Way Out is an experience that must be played with two players. Each player controls one of the main characters, Leo and Vincent, in a reluctant alliance to break out of prison and gain their freedom.' FROM games WHERE igdb_id = 36897 ON CONFLICT (game_id, language_code) DO NOTHING;
