INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Ark', 'Embark on an odyssey for the Lost Ark in a vast, vibrant world: explore new lands, seek out lost treasures, and test yourself in thrilling action combat. Define your fighting style with your class and advanced class, and customize your skills, weapons, and gear to bring your might to bear as you fight against hordes of enemies, colossal bosses, and dark forces seeking the power of the Ark in this action-packed free-to-play RPG.' FROM games WHERE igdb_id = 26128 ON CONFLICT (game_id, language_code) DO NOTHING;
