INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel Rats', '"Steel Rats is a visceral and groundbreaking evolution of the 2.5D action arcade genre, fusing destructive, octane-fuelled motorbike combat and death-defying stunt gameplay, set in a visually stylised retro future world. Become one with your bike as you master the realistic physics based controls of these powerful and deadly vehicles. Choose how you want to tear through the stylised and highly detailed environments of Steel Rats, traversing up, down left and right as your bike speeds fluidly in and out of the game world, over rooftops and through enemy-infested tunnels."' FROM games WHERE igdb_id = 74881 ON CONFLICT (game_id, language_code) DO NOTHING;
