INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '39 Days to Mars', '39 Days to Mars is a co-operative (and single-player) steampunk puzzle-adventure game. Step into the shoes of Sir Albert Wickes and The Right Honourable Clarence Baxter, two 19th century explorers who have chosen to pilot the HMS Fearful on its maiden voyage to Mars. When the steam engine runs out of coal, the ship''s cat shreds the navigation chart, and the tea gets cold, it becomes clear that interstellar transportation isn''t a walk in the park. It will take the talents of two players working together on the problems that arise to get to Mars in one piece.' FROM games WHERE igdb_id = 32125 ON CONFLICT (game_id, language_code) DO NOTHING;
