INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('timberman-vs', 99289, '2018-05-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27br.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcve.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timberman VS', 'Are you world-class wood chopper? Enter the digital forest and find out! Discover the Nintendo Switch version of this classic, casual game - slice and dice trees in an arcade-style, challenge your friends and be the fastest timberman alive! Timberman now features a single player challenge, to test your skills and unlock as much as 56 characters, and local games to have fun with your friends! Grab your trustworthy axe, become a true Timberman, and chop trees in 3, unique game modes: Classic Timberman: train your axe skills, gain exp to develop your account, and beat your personal high score - in a classic, single-player, infinite tree mode. Chop as fast as you can and avoid branches! Prove you''re the REAL THING! Hero mode: be the hero and rescue birds from their nest in a burning woods - gain eternal glory and sweet loot! Can you reach the top of a tree and find a golden egg? Race: join the race and be the fastest Timberman in a fun, tree-chopping competition! Play with up to 4 players and test your chopping skills against others in a crazy, fast-paced match! First on the finishing line WINS IT ALL! Join millions of players playing Timberman, now on Nintendo Switch - featuring brand new, exciting game modes, plenty of crazy new characters to unlock, and more fun than ever!' FROM games WHERE igdb_id = 99289 ON CONFLICT (game_id, language_code) DO NOTHING;
