INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demolish & Build 2018', 'Your company is going global. Use big machines to demolish huge buildings or go close and personal and use your hammer.  Buy land properties, upgrade your machines and hire workers in different parts of the world.  - Various construction and demolition machines  - 4 different world locations with freely navigable world  - Hire and manage workers  - 2 players cooperative multiplayer  - Specialized hand tools  - Demolition site dust control  - Finish contracts or use your machines to gather resources and earn cash  - Invest in your own properties  - Demolition site preparation  - Manage your company and make sure it''s rating goes up' FROM games WHERE igdb_id = 90102 ON CONFLICT (game_id, language_code) DO NOTHING;
