INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mothergunship', 'Our mission is clear, our determination strong, and our guns are very, very big. MOTHERGUNSHIP is a bullet-hell FPS hybrid facing you, Earth’s last hope, against the fleets of data-hoarding robotic alien invaders. Take the fight to the enemy, craft gun monstrosities that no reasonable person could ever lift, and experience randomized mayhem as you battle your way to the heart of the fleet to destroy the MOTHERGUNSHIP!' FROM games WHERE igdb_id = 27208 ON CONFLICT (game_id, language_code) DO NOTHING;
