INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slipstream', 'Slipstream is a racing game influenced and inspired by the OutRun series, SEGA games in general, Initial D, Vaporwave & Synthwave aesthetics and the spirit of 90s arcades. It uses a real pseudo3D engine to provide an authentic retro experience in a modern shell. After being funded via kickstarter in 2016 and delayed more times than the developer would like to admit, it was released independently for PC in 2018.' FROM games WHERE igdb_id = 75096 ON CONFLICT (game_id, language_code) DO NOTHING;
