INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R-Type Dimensions EX', 'This compilation once again includes the first two games, R-Type and R-Type II, both of which feature the original 2D graphics as well as a new 3D recreation, with the player being able to switch back and forth between the two modes at the press of a button. EX also featured new music remixes, whereas the original release used the arcade soundtrack.' FROM games WHERE igdb_id = 112105 ON CONFLICT (game_id, language_code) DO NOTHING;
