INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dot-t-e-dot-s-t-expected-behaviour', 86524, '2018-05-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29an.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2nso.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '.T.E.S.T: Expected Behaviour', '.T.E.S.T: Expected Behavior is a 3D first-person brain twister in a sci-fi setting. Solve puzzles to test your logic, think outside the box, act fast and use your skills to adapt to unfamiliar situations. .T.E.S.T is full of both new and classic mechanics, but they are so deep that some still aren''t fully revealed. The game will make this clear to you. Again and again you''ll see that each rule always has some additional nuance. This can keep going forever. Keys, doors, moving platforms, even jumping will open up from a whole new angle.' FROM games WHERE igdb_id = 86524 ON CONFLICT (game_id, language_code) DO NOTHING;
