INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('defiance-2050', 89554, '2018-07-10', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28qx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jernqbzn96ryar5d3key.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defiance 2050', '"Defiance 2050 is a futuristic free to play online shooter set in an extraordinary post-apocalyptic world with advanced alien technology. Fight on your own or alongside friends as you explore and unlock powerful weapons with extensive skill and customization systems." For the 5th anniversary of Defiance the game is being remade from the ground up. Some account information will be transferable from the original game. Account based purchases like character and loadout slots as well as specific unique titles, such as “Old School”, will also be transferred over. A reward system is also going to be added to the original game with players earning Valor which will also be usable in some way. More information on this system will be revealed later.' FROM games WHERE igdb_id = 89554 ON CONFLICT (game_id, language_code) DO NOTHING;
