INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('candleman-the-complete-journey', 81247, '2018-01-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28w2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arne4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candleman: The Complete Journey', 'Candleman: The Complete Journey is a unique puzzle platformer, where light is both a welcome ally and a deceptive foe. Take the role of a little candle who can burn for only 10 seconds, and venture through an unsettling darkness of challenging levels with a smooth difficulty curve. Use your wits to overcome obstacles based on the mechanics of light and shadow, while exploring a wide range of enchanted environments as you seek out the distant glow. Journey through enchanted worlds, each more mysterious than the last. Face innovative challenges rooted in the mechanics of light and shadow. Become immersed in a stunning fairytale, unlike anything you''ve seen before.' FROM games WHERE igdb_id = 81247 ON CONFLICT (game_id, language_code) DO NOTHING;
