INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo: Fireteam Raven', '"Halo: Fireteam Raven is a cooperative arcade sci-fi shooting game from arcade legends Raw Thrills and Play Mechanix in a unique partnership and collaboration with 343 Industries. Set in the timeframe of the original Halo: Combat Evolved, this new immersive experience hot-drops players feet first into the boots of Fireteam Raven – a group of elite Orbital Drop Shock Troopers (ODST) – on the surface of Alpha Halo as they try desperately to prevent the alien Covenant alliance from taking control of the ancient superweapon."' FROM games WHERE igdb_id = 102066 ON CONFLICT (game_id, language_code) DO NOTHING;
