INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('downward-spiral-horus-station', 86480, '2018-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2pyf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1bz1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Downward Spiral: Horus Station', 'Downward Spiral: Horus Station lures players through a lost vessel abandoned by its crew. Solving the mystery of the space station will take wits and ingenuity as you fight or avoid dangers unknown. Use the ship''s maintenance hardware - like bolt throwers, rail guns, and arc welders to take out threats, solve puzzles and find the truth of why Horus Station has been left drifting in space. Downward Spiral: Horus Station’s focus will be heavy on environmental storytelling, as the game features no dialogue or cinematics. Instead, players will have to piece together the plot through observation and interpretation as they navigate the derelict space station, accompanied by the electronic ambient soundtrack composed by platinum selling HIM frontman Ville Valo. Additionally, 3rd Eye Studios is introducing an innovative control system that rethinks how movement works in zero-gravity. Rather than just float, players will have to push themselves off of the environment to propel themselves forward, or use tools just as they would in deep space.' FROM games WHERE igdb_id = 86480 ON CONFLICT (game_id, language_code) DO NOTHING;
