INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conduct Together!', 'Conduct TOGETHER! is an addictive game of explosive railway action that will challenge your inner conductor. Conduct everything yourself or hand a Joy-Con controller to a friend for a hectic teamwork of commanding trains, switching tracks and avoiding collisions in increasingly challenging action-puzzles. Play with up to 4 friends for the ultimate party game!' FROM games WHERE igdb_id = 113078 ON CONFLICT (game_id, language_code) DO NOTHING;
