INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlelands Royale', 'Made for mobile, Battlelands Royale is a casual Battle Royale game for everyone to enjoy. With 32 players and 3-5 minute matches it’s a whole lot of fun! No waiting in lobbies; no complicated menus to navigate. Just play, parachute, loot, and survive!' FROM games WHERE igdb_id = 104311 ON CONFLICT (game_id, language_code) DO NOTHING;
