INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battery Jam', '"Battery Jam is a local multiplayer game of competitive territorial mayhem coming to Steam Early Access in January! Use the boombox and our patented rocket punch to smash your opponents, capture their tiles, and dominate the arena! Choose one of four Jammers and compete to have the most tiles at the end of every match! Take on your friends in free-for-all or team mode across four stages on two levels, with more on the way!"' FROM games WHERE igdb_id = 78159 ON CONFLICT (game_id, language_code) DO NOTHING;
