INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'When the Night Comes', 'When The Night Comes is an episodic fantasy otome game with supernatural elements. You are a Hunter, and you''ve been called to the quiet town of Lunaris to assist the local Enforcers with an investigation into a series of increasingly unsettling murders. Immerse yourself in the world of Witches, Vampires, Demons and Lycan''s as you slowly unravel the mystery that lies deep within the roots of the town.' FROM games WHERE igdb_id = 117139 ON CONFLICT (game_id, language_code) DO NOTHING;
