INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow Jewels Puzzle', 'The Snow Dragon''s icy breath is ready to destroy all it touches in the Mountain Lands. Only the magic of the Snow Jewels can stop the ruthless monster. It''s time for an average girl from our world to go to battle. Her pet Halburt has the rare gift of being able to distinguish Snow Jewels from regular gems. Collect chains of gems and help bring back peace and tranquility to the Mountain Lands!' FROM games WHERE igdb_id = 87134 ON CONFLICT (game_id, language_code) DO NOTHING;
