INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('no-trace', 36754, '2018-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rqojnmxgwp3miq0pomrw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Trace', '"No Trace is a top-down stealth action shooter that immerses the player in highly detailed and stylized environments set throughout iconic global destinations. Packed with creative, and deadly opportunities to complete objectives, No Trace allows the players to adapt and create their own play-style using stealth, action or a combination of both styles to complete the objectives detailed within each level.  Precision depth based shooting reinvigorates the top-down/twin stick shooter genre, with verticality providing the opportunity and ability to perform precision headshots on enemies, and target environmental hazards at varied heights (such as CCTV cameras).  Utilise the full range of abilities synonymous with an ex-elite special forces, master assassin, to meticulously plan your approach to a diverse range of challenges. Eliminate your enemies without detection, or use precision gunplay and/or close quarters combat to complete objectives. Adjacent areas are obscured, with NPCs and security devices hidden by fog of war. Peek through doors and vents to gain the advantage and obtain early information on enemy whereabouts.  Activate inspection mode at any point to pause the game and view points of interest, interactable objects, security systems; and study NPC profiles with randomised behavioral traits. The varying ways in which you complete the objective is up to you."' FROM games WHERE igdb_id = 36754 ON CONFLICT (game_id, language_code) DO NOTHING;
