INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abha', 'Abha is an old-school point-and-click adventure game. Experience a fantasy world and go on an initiation quest full of twists and turns. Find items, solve puzzles, and experience environments brimming with poetry. Abha is a young woman living in a village that was deserted after an attack by a warrior people. The thick jungle canopy obscures the sky. Abha decides to leave her homeland, her soul drawn to follow a new path. She''ll embark on a long journey…' FROM games WHERE igdb_id = 111036 ON CONFLICT (game_id, language_code) DO NOTHING;
