INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Witchkin', 'Witchkin is a first-person, single-player, PC horror game where you play as a child trapped in a rural Texas farmhouse filled with terrifying toys in the 1920s. Your goal is to search all the levels of the house, from the basement to the attic, to find your missing sister...and to stay alive. The game is based on the Texas legend of "The Candy Lady", Clara Crane, a Texas woman who was supposedly responsible for several missing children around the turn of the century.' FROM games WHERE igdb_id = 52271 ON CONFLICT (game_id, language_code) DO NOTHING;
