INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UnExplored: Unlocked Edition', 'Descend into the depths of the Dungeon of Doom and complete your quest: steal the Amulet of Yendor from the fearsome dragon and make it out alive. Unexplored is the roguelite that feels like a roguelike.  An accessible yet challenging action RPG that has won praise for its revolutionary level generation tech. Explore dangerous dungeons, forge magical items, solve mysterious puzzles and battle hundreds of foes.  Unexplored: Unlocked Edition includes the main game and its three DLC packs: Mithril Run, Ripley Run, and The Dark Ritual.' FROM games WHERE igdb_id = 98837 ON CONFLICT (game_id, language_code) DO NOTHING;
