INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yeli Orog', 'Yeli Orog is a FMV adventure game about an immense archaeological discovery: A bizarre stone tablet written in the Celtiberian language found buried underneath an ancient dolmen in northern Spain. The inscription written on the tablet tells a ghoulish tale believed to be the Celtiberian origin myth. You play the role of Johnny Robin, an archaeologist sent to Asturias, Spain to assist in the recovery of Celtiberian remains. Upon arrival to Asturias you find yourself unexpectedly transported to an alien world, experiencing first-hand the terrifying story written on the ancient tablet. If you are a fan of Myst-like games, interactive stories with puzzle elements, and FMV games, you will appreciate Yeli Orog.' FROM games WHERE igdb_id = 104331 ON CONFLICT (game_id, language_code) DO NOTHING;
