INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hardest Dungeon', 'The Hardest Dungeon is a roguelike-like action role playing game that is very focused on team management and survival. Your target is to collect "The Deck of Mulark", the first ever Tarot Deck created by your ancestors with immense power that can alter the world. Can you and your team survive this adventure in the hardest dungeon?' FROM games WHERE igdb_id = 99040 ON CONFLICT (game_id, language_code) DO NOTHING;
