INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brass-tactics', 36779, '2018-02-22', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dn2.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brass Tactics', 'Brass Tactics is a real-time strategy (RTS) game designed exclusively for virtual reality (VR), developed by Hidden Path Entertainment. Set in a steampunk-inspired world, players command massive armies from a tabletop-style battlefield, using intuitive hand gestures to deploy troops, build structures, and execute tactical maneuvers. The game offers both single-player and multiplayer modes, featuring AI skirmishes, cooperative challenges, and competitive battles. Players can customize their armies and upgrade units to adapt to different strategic playstyles. The immersive VR interface allows for seamless control, giving players a god-like perspective over the battlefield.' FROM games WHERE igdb_id = 36779 ON CONFLICT (game_id, language_code) DO NOTHING;
