INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Basilisk', 'The Basilisk is a genre-swapping horror platformer that focuses on you, a supercomputer, as the last hope to save mankind from an unknown virus. If you suffer from mental health issues, play at your own risk.' FROM games WHERE igdb_id = 104883 ON CONFLICT (game_id, language_code) DO NOTHING;
