INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('heathen-the-sons-of-the-law', 104848, '2018-12-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1kb2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fpvvdwx2ekytttav467c.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heathen - The sons of the law', 'HEATHEN is a solo adventure with an immersive first person view (F.P.S) created by 2 indie developers. Inspired by the novel "The island of Doctor Moreau" by HG Wells.  The English expedition "Peary & Scott" discovers an island populated by strange and ferocious creatures. Half-human, half-animal, they were created by the famous Dr. Moreau. Peary, a scientist and biologist, resumes his work.  At a time when the abolition of slavery continues to grow worldwide, Scott, a wealthy industrialist and close to the royal family, sees huge potential in those "beasts": Cheap, hardworking manpower, easily renewable, and gifted with remarkable physical abilities.  In just 20 years, in secret, Peary and Scott will create hundreds of these "beasts" and build an empire. Inevitably, however, humans will lose control of the island: The north is occupied by humans, trapped and hidden behind their wall; while the rest of the island is populated by various generations of "beasts", which are often hostile towards each other. Most degenerate very quickly, and fall in bestial madness.  This is where your story begins: you are one of those "beasts". Your task will be long and difficult: Explore, develop, understand and reclaim the island, while respecting the law of Moreau.  Will you keep your faith in humanity until the end of this journey ?' FROM games WHERE igdb_id = 104848 ON CONFLICT (game_id, language_code) DO NOTHING;
