INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Settlers 7: History Edition', 'Choose your own path to victory in The Settlers 7: Paths to a Kingdom, the long-anticipated sequel to the award-winning strategy game. Embark on an exciting quest to create, build and manage your kingdom in the most innovative, customizable and re-playable version ever! Let yourself be enchanted by the new world of Settlers with this modernized History Edition - in the midst of green forests and lush meadows, it will bustle again. You alone hold the fate of your kingdom in your hands. Which strategy will you choose?' FROM games WHERE igdb_id = 114447 ON CONFLICT (game_id, language_code) DO NOTHING;
