INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tanks VR', 'Tanks VR is a multiplayer tank game set in the events of World War II. Immerse yourself in engaging 5v5 battles with other players and see them react to your maneuvers. The intuitive controls allow you to operate a tank on your own. Pick a tank from your garage and use it to fight for the axis or allies.' FROM games WHERE igdb_id = 82401 ON CONFLICT (game_id, language_code) DO NOTHING;
