INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beckett', 'Beckett by The Secret Experiment is a surreal noir. A disturbing story of a missing-persons investigator, hired to find a young man suffering from a mental illness. It is a taste of the alternative - an experience that will make you question what it is to exist. It is a vivid musing on identity, memory and loss. It is unlike anything you will ever play. It wants to offend. Don''t let it. Poor, poor Beckett.' FROM games WHERE igdb_id = 89504 ON CONFLICT (game_id, language_code) DO NOTHING;
