INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wormszone-dot-io', 174615, '2018-03-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zk1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar15nk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WormsZone.io', 'A fun, dynamic game with cool graphics! Get growing your worm right now! You love games with tons of real fun and dynamic action? Then welcome to the Worms Zone.io, an awesome arcade, where you can become the great champion of the arena! Collect yummies and different powerups, defeat enemies, and become the biggest worm of them all! You think it''s hard? Relax, the rules are simple - explore the arena, collect all the food you see, and grow your worms as big as you can imagine - there are no limits! Stand out from the other players, choose a skin from the wardrobe, or create your own unique style. The further you go, the more skins you unlock. Worms Zone is also a PVP action game! Watch out for other players and try not to bump into them, otherwise you''ll have to start from scratch. However, if you manage to sneak and encircle them, you''ll get more points and all the food they had. It is so yummy! There are several tactics for becoming a champion: "fighter," "trickster" or "builder." Which one will you be? Worms Zone also has unique graphics! We keep it minimalistic and simple and you''ll love it!' FROM games WHERE igdb_id = 174615 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 174615 AND c.slug = 'azur-interactive-games' ON CONFLICT DO NOTHING;
