INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splinterlands', 'Splinterlands is a unique digital trading card game that allows players to truly own their cards and other in-game assets. Thanks to web 3.0 technology powered by the HIVE blockchain, each card in Splinterlands is a non-fungible token owned by a player. That means that players can do anything they want with their cards, including battling for rewards, holding as collectibles, trading on the peer-to-peer market, combining to level up, or even burning to obtain Dark Energy Crystals, the official in-game cryptocurrency of Splinterlands.' FROM games WHERE igdb_id = 165055 ON CONFLICT (game_id, language_code) DO NOTHING;
