INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Inpatient', 'A twisting tale of terror. Life and death decisions Open your eyes... and prepare yourself for the dread of unforgettable psychological horror. Set 60 years before the nerve-shredding events of "Until Dawn", you awaken in a strange medical facility, with no memory. It''s up to you to discover why you''re trapped within Blackwood Pines Sanatorium - and uncover a chilling conspiracy lurking within its shadows.' FROM games WHERE igdb_id = 37089 ON CONFLICT (game_id, language_code) DO NOTHING;
