INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Don''t Die Mr Robot! DX', 'Don’t Die, Mr. Robot! DX is a remixed version of the much-loved arcade bullet-hell avoid ‘em up, completely remastered and rejuvenated for Nintendo Switch. Deep in the electro-abyss lives a little robot who loves to eat exploding fruit. He also likes staying alive. That’s where you come in… Get the fruit. Avoid the enemies. Try not to die. (Spoilers: you will die)' FROM games WHERE igdb_id = 99306 ON CONFLICT (game_id, language_code) DO NOTHING;
