INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Total War: Arena', 'Total War: Arena is a free-to-play, team-based strategy game, putting players in the middle of epic-scale realtime battles. Join 10v10 battles designed for multiplayer realtime strategy fans, with armies of thousands on the battlefield. Control three units of warriors, led by an iconic commander from history, each with their own battle style. Level up commanders and units to open up more specialist skills, weaponry, armour and abilities. Decisive strategies, combat tactics and teamwork decide who is victorious.' FROM games WHERE igdb_id = 12982 ON CONFLICT (game_id, language_code) DO NOTHING;
