INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squirm', 'After a previous adventure, you and your rat friend stop for a snooze. When you wake up, the rat is gone and strange creatures have appeared across the land as if from out of nowhere! What has happened while you were asleep? Where is your rat friend? Get to the bottom of these mysteries by squirming your way through tons of trap-infested levels!' FROM games WHERE igdb_id = 89252 ON CONFLICT (game_id, language_code) DO NOTHING;
