INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pumpkin-death-garden', 110936, '2018-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1hc9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5nuj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pumpkin Death Garden', '2D top-down arcade survival shooter, in which you grow and defend your pumpkin patch from bugs! Get competitive on the leaderboard! Your score is the amount of bugs you killed. Are you a shotgun person, a sniper rifle person, or an assault rifle person? Try them out to find your favourite. Each has a unique play style with strengths and drawbacks! When you level up, you are given a choice of three random gun mods. Sometimes you''ll have to improvise, and work with whatever you get! Earn coins when you play, and spend them on upgrades! Currently 40 upgrades available, with more planned for the next update! There is no DLC, and no in-game purchases. You get the full game! Want to sit back, relax, and shoot some bugs? Play the game on normal speed. Looking for an intense challenge? Try the game on 1.5x speed, or even 2x speed! W, A, S and D to move. Use the mouse to aim, and left click to shoot. Feel free to leave a review. Enjoy!' FROM games WHERE igdb_id = 110936 ON CONFLICT (game_id, language_code) DO NOTHING;
