INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zarvot', 'Zarvot is a voxelike multiplayer arena. Use finely tuned and balanced weapons in the ultra-competitive mode, or duke it out on party-centric EXPLOSIONS mode with powerups, custom maps, and a variety of game types! Fast paced action, a wide variety of powerups, and custom level support! There are a lot of features in this baby. With skill-based gameplay and decisive victories, there''ll be no doubt over who is the best at Zarvot. Beat your friends up and explode their cubes.' FROM games WHERE igdb_id = 12502 ON CONFLICT (game_id, language_code) DO NOTHING;
