INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glowing Cat', 'A mini game where with the help of glowing animals you can capture and collect variety of species. light attracts the insects and bugs to gather around and can be captured and saved in the album.  Multiple mini games inside the game for recharging the battery keep the gaming experience non stop and running.  Team choice and event participation to contribute in team victories.  Also with many more features, screenshots with favorite species can be taken and shared among family and friends.' FROM games WHERE igdb_id = 112098 ON CONFLICT (game_id, language_code) DO NOTHING;
