INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Korgan', 'Korgan is an episodic dungeon-crawler game.  While playing the story mode you can switch your character in real time to face different kind of enemies or obstacles.  Combine their abilities: freeze an enemy with the Mage, switch your character to Warrior and finish him with brute force, or perhaps shoot him from a safe range with the Hunter? Each character have their own abilities, strengths and weakness.' FROM games WHERE igdb_id = 83810 ON CONFLICT (game_id, language_code) DO NOTHING;
