INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendo Labo: Toy-Con 03 - Vehicle Kit', 'This brand-new Nintendo Labo kit contains materials to build a variety of customisable cardboard creations called Toy-Con, including a Car, a Submarine, a Plane, a Pedal, two Keys and more. Insert one of the assembled Keys into any of the vehicles to enjoy a variety of fun games and activities. Changing between vehicles while adventuring is easy – just remove the key from one and slot it into another to transform from an airplane pilot to a submarine captain.' FROM games WHERE igdb_id = 106288 ON CONFLICT (game_id, language_code) DO NOTHING;
