INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meteorfall-journey', 88223, '2018-01-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qoo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sl2gpp561ltvmk4jnuq7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meteorfall: Journey', 'Meteorfall is a deck-building roguelike. You''ll choose your class from one of four unique adventurers, and then set out with a deck consisting of some basic attack cards. During the course of your adventure, you''ll be presented with the opportunity to add powerful new cards to your deck. No adventure would be complete without slaying a few monsters that get in your way. In battle, you''ll draw cards from your ability deck. Each time you draw a card, you''ll be able to swipe right to play the card, or swipe left to skip a turn and regain some stamina. Between battles, you''ll venture through a variety of locations, represented by an encounter deck. You''ll encounter blacksmiths that can upgrade your cards, temples that can help you optimize your deck, and mysterious characters that will make you all sorts of bargains. The tactical strategy of combat micro-decisions mixed with the strategic element of deck-building provides a compelling and deep gameplay experience. As with all roguelikes, death is permanent. You''ll earn some gems that you can use to unlock new cards, but it''s back to the drawing board after that. Start out with a new adventurer and set out on your quest once again. The good news is that Meteorfall is different every time you play - you''ll encounter different locations, different enemies, and different quests. Part of the challenge is adapting to the challenging situations the game puts you in, given the cards available. Good luck hero - it''s time to end the Uberlich''s cycle of destruction!' FROM games WHERE igdb_id = 88223 ON CONFLICT (game_id, language_code) DO NOTHING;
