INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lemmings', 'Lemmings is a mobile puzzle game developed by Sad Puppy for Android and iOS. It is a free-to-play remake of the original 1991 title, redesigned for touch controls and vertical screen play. Players guide lemmings to safety by assigning skills that enable them to navigate obstacles and hazards. The game features hundreds of levels across themed worlds, with a gradual increase in difficulty. It incorporates energy-based gameplay and in-app purchases for progression and cosmetic items.' FROM games WHERE igdb_id = 113439 ON CONFLICT (game_id, language_code) DO NOTHING;
