INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blade-and-wings-future-fantasy-3d-anime-mmorpg-game', 110819, '2018-04-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1h2c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5igf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blade and Wings: Future Fantasy 3D Anime MMORPG Game', 'The new version featuring Epic pet - Maid has been released! Pay attention to the upcoming events to get the adorable pet!  Blade & Wings is a 3D anime online action role-playing game that rated as a promising mobile MMORPG, which brings high quality graphics with a captivating story line and features a variety of challenging quests. To be distinguished from the crowded realistic style action RPG games, Blade & Wings brings a bright and fresh anime.  For too long, players have become accustomed to battling against just NPCs in traditional games. Blade & Wings uniquely impact this primal setting and reverses the identity between NPC and player. In Blade & Wings, you become one of the NPC forces who break their seal and people surrounding you are the players and furious enemies. Join this epic anime game and show your enemies no mercy as you fire them out of this chaos then build a new future with order.' FROM games WHERE igdb_id = 110819 ON CONFLICT (game_id, language_code) DO NOTHING;
