INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MegaWorld', 'Autonomous Web3 city builder game. Construct buildings to produce Resources required by other buildings to be constructed, maintained and operated. Trade Resources on the open market and reward Couriers to complete delivery orders in your buildings to boost production. Explore 3 cities built by players and complete delivery orders in buildings for rewards. Use proceeds to upgrade your Avatar, acquire an apartment Unit in a building, use public Transport or purchase a Car to quickly travel on the gaming map.' FROM games WHERE igdb_id = 286568 ON CONFLICT (game_id, language_code) DO NOTHING;
