INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Spiral Scouts', 'Join Remae, the newest member of the Spiral Scouts, on her slap-tastic puzzle solving adventure through a world of crazy characters and redonkulous realms. Experience a fartwarming tale of personal growth, self discovery, poop, wieners and butts.  The founders of the Spiral Scouts have been isolated and sealed away within their realms by a mysterious force, preventing them from gathering together at the Citadel to perform the Spiral Ceremony; a sacred tradition of paramount importance. It''s up to you to travel to each realm and earn enough Scout Badges to break the seals and reunite the founders before it''s too late!' FROM games WHERE igdb_id = 96200 ON CONFLICT (game_id, language_code) DO NOTHING;
