INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarDrone', 'StarDrone is a high-kinetic action puzzle with a mix of arcade, pinball, breakout, physics, and collect-the-objects. Cause your attackers to crash with rapid speed while collecting gems and power-up enhancements. Explore the levels to find key power-ups and earn more bonus points that will ...' FROM games WHERE igdb_id = 82029 ON CONFLICT (game_id, language_code) DO NOTHING;
