INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Bash Boom', 'Perfect for the whole family, Big Bash Boom mixes all the big hitting thrills of T20 cricket with instantly accessible arcade action. Anyone, anywhere, will be able to jump in and be hitting the ball like a pro with Big Bash Boom, which is fully licensed and includes all teams and players featured in this year’s KFC Big Bash League (BBL) and rebel Women’s Big Bash League (WBBL) – meaning fans can take control of their favourite players.' FROM games WHERE igdb_id = 112895 ON CONFLICT (game_id, language_code) DO NOTHING;
