INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sdorica', 'An RPG title featuring masterfully crafted audio and visuals along with a massive volume of story to boot. With over 30 characters each with unique skills and abilities, you can mix and match your team of three and strategize your way through waves of battles. Player get to unravel the story as they progress, allowing them to sink into this original experience.' FROM games WHERE igdb_id = 96095 ON CONFLICT (game_id, language_code) DO NOTHING;
