INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Islands of Nyne: Battle Royale', 'Islands of Nyne: Battle Royale is an online, competitive, first-person shooter inspired by works such as Battle Royale and The Hunger Games. Handpicked by a mysterious alien race and taken to a distant homeworld, 100 players must fight each other to the death in 1 of 3 ever-shrinking arenas. Drop in, find a weapon, and stay alive... for only 1 can emerge victorious. The rest must die!' FROM games WHERE igdb_id = 51548 ON CONFLICT (game_id, language_code) DO NOTHING;
