INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dude, Stop', '"So, I made a game, right? I filled it with harmless funny puzzles, narrated it a little bit, and then players started making fun of it! They broke the game and ignored my rules! They... they... laughed at me! As if it was some kind of a joke! Why do they have to be so mean?!" - developer of "Dude, Stop".' FROM games WHERE igdb_id = 29965 ON CONFLICT (game_id, language_code) DO NOTHING;
