INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('antigraviator', 76566, '2018-06-06', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28u5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aroqc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Antigraviator', 'In the year 2210, racing has evolved far beyond its expected limits. New terraforming capabilities paired with scientific breakthroughs in the field of antigravity have given birth to a new spectacle: the Antigraviator tournament. In Antigraviator, players will race on exquisitely detailed stages, full of light-speed danger, chaos and mayhem. Gamers will guide their Grav in three gameplay modes across four different worlds with three tracks each. These dynamic courses come to life, while pushing the power of Unity to the limit. Players can challenge their friends in the fiercely competitive multiplayer modes, either online or in split-screen mode. Race yourself to the top of the worldwide leaderboard and earn special ranked skins. Gamers can sabotage their fellow racers by activating hover mines, damaging the environment to create a rockslide, causing tunnels to collapse, firing missiles from rocket launchers along the track and many more fiendish tricks. Gravs are customizable, but choose wisely: deciding on one upgrade may mean compromising on another. Strategically tailor-make Gravs to gain the upper hand in races or face the crushing prospect of defeat. In addition to the customization options, unlockable skins will be available free of charge. In this futuristic high-octane racing game, defying gravity is the least of your concerns.' FROM games WHERE igdb_id = 76566 ON CONFLICT (game_id, language_code) DO NOTHING;
