INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fishing-barents-sea', 22356, '2018-02-07', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27qi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnon.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fishing: Barents Sea', 'Fishing: Barents Sea is a simulator game for PC, about industrial fishing, you will be put in a role as a fishboat captain. Starting out with a small boat you inherited from your grandfather, earn money fishing to buy upgrades, bigger&better boats and more. Make your grandfather proud! Learn to catch various types of fish with different boats and sets of fishing gear. When inside a port you can visit the bar for hiring crew or get missions, visit docks to repair or buy upgrades for your boat, visit the bank to take a loan or go to the shop to buy supplies and other upgrades. In your homeport you can visit and upgrade your cabin and much more. You will play in an open world environment over parts of northern Norway, maneuver your boat around the map to find the best fishing spots using your fish sonar, radar and GPS. The gameplay will be an easy to learn, hard to master experience when using various fishing tools to catch your fish. Experience an atmospheric and stylish gameworld, with day and night cycle, seasonal effects, advanced resource and weather system. Everything is calculated from real maps, real boats, real fishes inluding age, breeding areas, depth, fish quotas, collectable items and much more.' FROM games WHERE igdb_id = 22356 ON CONFLICT (game_id, language_code) DO NOTHING;
