INSERT INTO game_artwork (game_id, url, artwork_type, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/arnon.jpg', 'promotional', 0, true FROM games WHERE igdb_id = 22356 ON CONFLICT DO NOTHING;
INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=aQjOebmf2ug', 'https://img.youtube.com/vi/aQjOebmf2ug/maxresdefault.jpg', 'Trailer', 'trailer', 0, true FROM games WHERE igdb_id = 22356 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 22356 AND rs.code = 'ESRB' AND r.code = 'E' ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'en', 'English', false, true, true FROM games WHERE igdb_id = 22356 ON CONFLICT DO NOTHING;
